export default [{"id":1,"title":"ولادة النبي محمد بن عبدالله صلى الله عليه وسلم .","date":["العام الهجري :53ق هـ","العام الميلادي :571"],"text":"اختلفَ أهلُ السِّيَر والتَّاريخِ في تحديدِ يومِ وشهرِ وِلادتِه صلى الله عليه وسلم واتَّفقوا على أنَّ مِيلادَه صلى الله عليه وسلم كان يومَ الاثنينِ من عامِ الفيلِ.قال ابنُ القيِّم: \"لا خِلافَ أنَّه وُلِدَ صَلَّى اللَّهُ عَليهِ وسلَّم بجَوفِ مكَّة، وأنَّ مَولِدَه كان عامَ الفيلِ\". عنِ ابنِ عبَّاس رضِي الله عنهُما أنَّه قال: (وُلِدَ رسولُ الله صلى الله عليه وسلم عامَ الفيلِ)، وهو الَّذي لا يَشكُّ فيه أحدٌ من العلماءِ. ونقل خليفةُ بنُ خيَّاط وابنُ الجزَّار وابنُ دِحيةَ وابنُ الجوزيِّ فيه الإجماعَ. وأمَّا مولدُه يومَ الاثنينِ، فعن أبي قَتادةَ الأنصاريِّ رضي الله عنه قال: \" سُئل صلى الله عليه وسلم  عن صومِ يومِ الاثنينِ؟ قال: \"ذاكَ يومٌ وُلدتُ فيهِ، ويومٌ بُعثتُ أو أُنزلَ عليَّ فيهِ\". قال ابنُ كَثيرٍ: \"وأبعدَ بل أخطأَ مَن قال: وُلِدَ يومَ الجُمعةِ لِسبعَ عشرةَ خلتْ من ربيعٍ الأوَّلِ\". أمَّا موضعُ الخِلافِ فقد كان في تحديدِ الشَّهرِ واليومِ منه،  رَوى ابنُ إسحاقَ عن نَفَرٍ من أصحابِ رسولِ الله صلى الله عليه وسلم قالوا له: يا رسولَ الله، أخبرنا عن نَفسِك. قال: (نعمْ، أنا دعوةُ أبي إبراهيمَ، وبُشرى عيسى، ورأتْ أمِّي حين حملتْ بي أنَّه خرج منها نورٌ أضاءَ لها قُصورَ الشَّام). وكانت وِلادتُه صلى الله عليه وسلم بعدَ وفاةِ والدِه عبدِ الله، حيث كان حَمْلًا في بطنِ أمِّه حين تُوفِّي والدُه، فنشأ صلى الله عليه وسلم يتيمًا. وكانت وِلادتُه في دارِ أبي طالبٍ بِشِعبِ بني هاشمٍ."},{"id":2,"title":"حادِثةُ شَقِّ صدرِ النَّبيِّ صلَّى الله عَليهِ وسلَّم الأُولى .","date":["العام الهجري :49ق هـ","العام الميلادي :575"],"text":"عن أنسِ بنِ مالكٍ: أنَّ رسولَ الله صلَّى الله عَليهِ وسلَّم أتاهُ جبريلُ صلَّى الله عَليهِ وسلَّم وهو يلعبُ مع الغِلمانِ، فأخذهُ فصرعهُ، فشَقَّ عن قَلبِه، فاستخرجَ القلبَ، فاستخرجَ منه عَلَقَةً، فقال: هذا حَظُّ الشَّيطانِ منكَ، ثمَّ غسلهُ في طِسْتٍ من ذهبٍ بماءِ زمزمَ، ثمَّ لَأَمَهُ، ثمَّ أعادهُ في مكانِه، وجاء الغِلمانُ يَسعَون إلى أمِّه -يعني ظِئْرَهُ-فقالوا: إنَّ محمَّدًا قد قُتل، فاستقبلوه وهو مُنْتَقِعُ اللَّونِ\". قال أنسٌ: «وقد كنتُ أَرى أثرَ ذلكَ المِخْيَطِ في صدرِه»."},{"id":3,"title":"وفاة أم النبي آمنة بنت وهب وحضانة أم أيمن له صلى الله عليه وسلم .","date":["العام الهجري :48ق هـ","العام الميلادي :575"],"text":"لمَّا بَلَغَ رسولُ الله صلَّى اللهُ عليه وسلَّم سِتَّ سنينَ، خرجَتْ به أُمُّه السيِّدةُ آمنةُ بنتُ وهبٍ إلى أخوالِه بني عَديِّ بن النَّجَّار تَزورُهم به، ومعه حاضِنَتُه أمُّ أيمنَ رَضي اللهُ عنها، وهم على بَعيرَين، فنَزَلَت به أُمُّه في دارِ النابغةِ عند قبرِ أبيه عبدِ الله بن عبدِ المُطَّلِب، فأقامَت به عند أخوالِه شهرًا، ثم رَجَعَت به أُمُّه إلى مكةَ، فلمَّا كانوا بالأبواءِ توُفِّيَت أُمُّه آمِنةُ بنتُ وهبٍ، ورَجَعَت به أُمُّ أيمنَ رَضي اللهُ عنها -واسمُها: بَرَكةُ بِنتُ ثَعلَبةَ بنِ حِصنٍ-، وكانت أمُّ أيمنَ رَضي اللهُ عنها تحبُّ النبيَّ صلَّى اللهُ عليه وسلَّم حُبًّا شديدًا وتَعتني به غايةَ الاعتِناءِ، وتَحوطُه برِعايَتِها وشَفقَتِها، وكان النبيُّ صلَّى اللهُ عليه وسلَّم يَبَرُّها ويُحسِنُ إليها، ولمَّا كَبِرَ صلَّى اللهُ عليه وسلَّم أعتَقَها، ثم أنكَحَها زيدَ بنَ حارِثةَ رَضي اللهُ عنه الذي أنجَبَت منه أُسامةَ بنَ زيدٍ رَضي اللهُ عنهما، وقد توُفِّيَت أمُّ أيمنَ رَضي اللهُ عنها بعدما توفِّي رسولُ الله صلَّى اللهُ عليه وسلَّم بخَمسةِ أشهُرٍ."},{"id":4,"title":"كفالة عبد المطلب رسول الله صلَّى اللهُ عليه وسلَّم ومعرفته بشأنه .","date":["العام الهجري :48ق هـ","العام الميلادي :575"],"text":"لمَّا تُوفِّيتِ آمنةُ والدةُ الرسول عليه الصلاة والسلام وعُمُرُه ستُّ سنواتٍ، صارت كَفالَتُه إلى جدِّه عبدِ المطلب بن هاشِمٍ، وكان عبدُ المطلب ذا شَرفٍ في قومِه وفَضلٍ، وكانت قُريشٌ تُسمِّيه الفضلَ؛ لسَماحتِه وفضلِه، وتولَّى أمْرَ الرِّفادةِ والسِّقايةِ بعد موتِ أبيه هاشمِ بن عبد مَنافٍ. وكان عبدُ المطلب يُحِبُّ حفيدَه مُحمَّدًا حبًّا عظيمًا، ويُقدِّمُه على سائِرِ بنيه، ويَرِقُّ عليه أكثَرَ مِن رِقَّتِه على أولادِهِ، قال ابنُ إسحاقَ‏ رحمه الله:‏ \"وكان رسولُ الله صلَّى اللهُ عليه وسلَّم مع جدِّه عبد المطلب بن هاشم -يعني: بعدَ موتِ أُمِّه آمنةَ بنتِ وَهبٍ-؛ فكان يُوضَعُ لعبد المطلب فِراشٌ في ظلِّ الكعبة، وكان بَنوه يَجلِسون حول فِراشِه ذلك حتى يَخرُج إليه، لا يَجلِسُ عليه أحدٌ مِن بنيه إجلالًا له؛‏ فكان رسولُ الله صلَّى اللهُ عليه وسلَّم يأتي وهو غُلامٌ جَفْرٌ -أي: ممُتلئٌ قويٌّ- حتى يَجلِسَ عليه؛ فيأخذُه أعمامُه ليؤخِّروه عنه؛ فيقول عبدُ المطلب إذا رَأى ذلك منهم‏:‏ دَعوا ابني؛ فوالله إنَّ له لَشأنًا، ثم يُجلِسُه معه على فِراشِه، ويَمسَحُ ظهرَه بيدِه، ويَسُرُّه ما يراه يَصنَعُ‏\". وكان عبدُ المطلب لا يَأكلُ طَعامًا إلَّا يقولُ:‏ \"عَلَيَّ بابني!\" فيُؤتَى به إليه‏.‏ ولمَّا حَضَرت عبدَ المطلب الوفاةُ أوصى أبا طالبٍ بحِفظِ رسولِ الله صلَّى اللهُ عليه وسلَّم وحياطَتِه."},{"id":5,"title":"وفاة عبد المطلب ووصيته لأبي طالب برسول الله صلَّى اللهُ عليه وسلَّم .","date":["العام الهجري :46ق هـ","العام الميلادي :577"],"text":"لمَّا بَلَغَ رسولُ الله صلَّى اللهُ عليه وسلَّم ثَمانيَ سنواتٍ توُفِّي جدُّه عبد المطلب. وكان عبدُ المُطَّلِب لمَّا حَضَرته الوفاةُ أوصى ابنَه أبا طالبٍ بحِفظِ رسول اللَّه صلَّى اللهُ عليه وسلَّم، وحياطَتِه، والقيامِ عَليهِ، وأوصَى به إلى أبي طالِبٍ؛ لأنَّ عبدَ الله -والِدَ النبيِّ صلَّى اللهُ عليه وسلَّم- وأبا طالبٍ كانا لأُمٍّ واحدةٍ، فلمَّا مات عبدُ المطلب كان أبو طالِبٍ هو الذي يَلي أمْرَ رسولِ اللَّه صلَّى اللهُ عليه وسلَّم بعد جدِّه. ورَوَى ابنُ سعدٍ، وابنُ عساكِرَ عن ابن عبَّاسٍ رَضي اللهُ عنهما، وغَيرِه، قالوا: لمَّا توُفِّيَ عبدُ المطلب قَبَضَ أبو طالبٍ رسولَ اللَّه صلَّى اللهُ عليه وسلَّم فكان يكونُ معه، وكان يُحِبُّه حبًّا شديدًا لا يُحِبُّ وَلَدَه مِثله، وكان لا يَنامُ إلَّا إلى جَنبِه، وكان يَخُصُّه بالطَّعامِ، وكان عيالُ أبي طالِبٍ إذا أكلوا جميعًا أو فُرادَى لم يَشبَعوا، وإذا أكَل معهم رسولُ اللَّه صلَّى اللهُ عليه وسلَّم شَبِعوا. وكان أبو طالِبٍ إذا أراد أن يُغدِّيَهم أو يُعشِّيَهم يقول: كما أنتُم حتى يَحضُرَ ابني. فيَأتي رسولُ اللَّه صلَّى اللهُ عليه وسلَّم فيأكُلُ معهم فيُفضِلون من طَعامِهم، وإن لم يَكُن معهم لم يُشبِعْهم، وإن كان لَبنًا شَرِبَ هو أوَّلَهم ثم يتناوَلُ العيالُ القَعْبَ -إناءٌ ضخمٌ كالقَصْعةِ- فيَشرَبون منه فيُروَون عن آخِرِهم من القَعبِ الواحِدِ، وإن كان أحدُهم لَيَشرَبُ قَعبًا وَحدَه، فيقول أبو طالبٍ: \"إنَّكَ لَمُبارَكٌ!\"."},{"id":6,"title":"سفر النبي صلَّى اللهُ عليه وسلَّم مع عمه أبي طالب إلى الشام .","date":["العام الهجري :42ق هـ","العام الميلادي :581"],"text":"لمَّا تمَّ للنبيِّ صلَّى اللهُ عليه وسلَّم من العُمُرِ اثنَتا عَشْرةَ سنةً، سافر عمُّه أبو طالِبٍ إلى الشَّامِ في رَكبٍ للتِّجارةِ، فأخَذهُ معه. ولمَّا نزلَ الرَّكبُ (بُصرَى) مرّوا على راهِبٍ هناك يُقال له (بَحيرَا)، وكان عليمًا بالإنجيلِ، خبيرًا بالنَّصرانيَّةِ، وهناك أبصرَ بَحيرَا النبيَّ صلَّى اللهُ عليه وسلَّم، فجَعَلَ يتأمَّلُه ويُكلِّمُه، ثم الْتَفَتَ إلى أبي طالبٍ فقال له: ما هذا الغُلامُ مِنكَ؟ فقال: ابني (وكان أبو طالِبٍ يَدعوه بابنِه؛ لشدَّةِ محبَّتِه له وشَفَقَتِه عليه). فقال له بَحيرَا: ما هو بِابنِك، وما ينبغي أن يكونَ أبو هذا الغُلامِ حيًّا. فقال: هو ابنُ أخي. قال: فما فَعَل أبوه؟ قال: مات وأُمُّه حُبلَى به. قال بَحيرَا: صدقتَ. فارجِعْ به إلى بلدِه واحذَرْ عليه يهودَ؛ فوالله لئنْ رأوْهُ هنا لَيَبْغُنَّهُ شرًّا؛ فإنَّه كائنٌ لابنِ أخيك هذا شأنٌ عظيمٌ. فأسرَع به أبو طالبٍ عائدًا إلى مكَّةَ. وروَى التِّرمذيُّ: أنَّ أبا طالبٍ خرج إلى الشَّامِ، وخَرَج معه النبيُّ صلَّى اللهُ عليه وسلَّم في أشياخٍ من قُرَيشٍ؛ فلمَّا أشرَفوا -اقتَرَبوا- على الرَّاهِب -يَعني: بَحيرَا- هَبَطوا فحَلُّوا رِحالَهم؛ فخَرَج إليهمُ الراهبُ، وكانوا قبل ذلك يَمرُّون به فلا يخرُجُ إليهم ولا يَلتفِتُ إليهم، قال: وهم يَحُلُّون رِحالَهم؛ فجَعَل يَتخلَّلُهمُ الرَّاهبُ حتى جاء فأخَذ بيَدِ رسولِ الله صلَّى اللهُ عليه وسلَّم، فقال: هذا سيِّدُ العالَمين، هذا رسولُ ربِّ العالَمين، يبعَثُه اللهُ رحمةً للعالَمين، فقال له أشياخٌ من قُريشٍ: ما عِلمُك؟ قال: إنَّكم حين أشرفتُم من العقبةِ لم يبقَ شجرٌ ولا حجرٌ إلا خرَّ ساجدًا، ولا يَسجُدانِ إلا لنبيٍّ، وإنِّي أعرِفُه بخاتَمِ النبوَّةِ أسفلَ من غُضروفِ كَتِفِه مثلِ التُّفَّاحةِ، ثم رَجَع فصَنَع لهم طعامًا، فلمَّا أتاهم به، وكان هو -أي: الرسولُ صلَّى اللهُ عليه وسلَّم- في رِعيةِ الإبلِ، قال: أرسِلوا إليه. فأقبَلَ صلَّى اللهُ عليه وسلَّم وعليه غَمامةٌ تُظِلُّه، فلما دنا من القَومِ، وَجَدَهم قد سَبَقوه إلى فيءِ -ظلِّ- الشَّجرةِ، فلمَّا جلس رسولُ الله صلَّى اللهُ عليه وسلَّم مالَ فَيءُ الشجرةِ عليه، فقال بَحيرَا: انظُروا إلى فَيءِ الشجرةِ مالَ عليه! قال: فبينما هو قائمٌ عليهم، وهو يُناشِدُهم ألَّا يَذهَبوا به إلى الرُّومِ؛ فإنَّ الرُّومَ إن رأوه عَرَفوه بالصِّفةِ فيقتُلونَه، فالْتفَتَ فإذا بسَبعةٍ قد أقبلوا من الرُّومِ فاستَقبَلَهم، فقال: ما جاء بكم؟ قالوا: جِئنا أنَّ هذا النبيَّ خارِجٌ في هذا الشَّهرِ، فلم يبقَ طريقٌ إلَّا بُعِثَ إليه بأُناسٍ، وإنَّا قد أُخبِرنا خَبَرَه، فبُعِثنا إلى طريقِك هذا، فقال: هل خَلَفَكم أحدٌ هو خيرٌ منكم؟ قالوا: إنَّما أُخبِرنا خَبَرَه إلى طريقِكَ هذا. قال: أفَرَأيتم أمرًا أراد اللهُ أن يقضيَه، هل يستطيع أحدٌ من الناس ردَّه؟ قالوا: لا، قال: فبايَعوه، وأقاموا معه عنده. قال: فقال الرَّاهبُ بَحيرَا: أنشُدكم اللهَ أيُّكم وَليُّه؟ قال أبو طالب: فلم يزَل يُناشِدُه حتى ردَّه أبو طالِبٍ\"."},{"id":7,"title":"حرب الفِجَار، وشهود النبي صلَّى اللهُ عليه وسلَّم لها .","date":["العام الهجري :39ق هـ","الشهر القمري : شوال","العام الميلادي :585"],"text":"لمَّا بلغَ رسولُ الله صلَّى اللهُ عليه وسلَّم أربعَ عشرةَ سنةً أو خمسَ عشرةَ سنةً هاجت حربُ الفِجارِ بين قُريشٍ ومَن معها مِن كِنانةَ وبين قَيسِ عَيلانَ، وهو من أعظمِ أيَّامِ العربِ، وكان الذي أهاجَها: أنَّ عُروةَ الرَّحَّالَ بنَ عتبة بن ربيعةَ أجارَ لَطيمةً للنُّعمانِ بن المنذرِ، فقال له البَرَّاضُ بنُ قيسٍ -أحدُ بني ضَمْرةَ بنِ بكرِ بنِ عبدِ مناةَ بنِ كنانةَ-: أتُجيرُها على كِنانةَ؟! قال: نعم، وعلى الخَلقِ. فخَرَجَ عُروةُ الرَّحَّالُ وخَرَج البَرَّاضُ يَطلُبُ غَفْلَتَه حتى إذا كان بِتَيْمَنَ ذي ظِلالٍ بالعاليةِ غَفَلَ عُروةُ؛ فوَثَب عليه البَرَّاضُ فقَتَله في الشَّهرِ الحَرامِ؛ فلذلك سُمِّي الفِجارَ؛ فأتى آتٍ قُريشًا فقال: إنَّ البَّرَّاضَ قد قَتَل عُروةَ وهو في الشَّهرِ الحَرامِ بعُكاظٍ، فارتَحَلوا وهوازِنُ لا تشعُرُ، ثم بلغهمُ الخبرُ فاتَّبَعوهم فأدركوهم قبل أن يدخلوا الحرمَ، فاقتتلوا حتى جاء الليلُ ودخلوا الحرمَ فأمسَكَت عنهم هوازِنُ ثم الْتَقَوا بعد هذا اليومِ أيَّامًا عديدةً والقومُ يتساندون، وعلى كلِّ قَبيلٍ من قُريشٍ وكِنانةَ رئيسٌ منهم، وعلى كل قَبيلٍ من قيسٍ رئيسٌ منهم. وشَهِد رسولُ الله صلَّى اللهُ عليه وسلَّم بعضَ أيَّامِهم، وهو يومُ النَّخلةِ، وكان لرسولِ الله صلَّى اللهُ عليه وسلَّم يومئذٍ أربعَ عشرةَ سنةً. ويُقالُ: عِشرون سَنةً.وبعد مُنصَرَفِهم منه في ذي القِعدةِ كان حِلفُ الفُضولِ، وسببُه: أنَّ رجلًا من زَبيدٍ من أهلِ اليمن باع سلعةً من العاصِ بن وائلٍ السَّهميِّ فمَطَله بالثَّمنِ؛ فصَعِدَ أبا قُبَيسٍ وصاح وذَكَر ظِلامَتَه. فعَقَدت قُريشٌ حِلفَ الفُضولِ لنُصرةِ المظلوم، وقد شَهِد النبيُّ صلَّى اللهُ عليه وسلَّم هذا الحِلفَ معهم."},{"id":8,"title":"حِلْفُ الفُضولِ بين قبائل قريش .","date":["العام الهجري :33ق هـ","الشهر القمري : ذي القعدة","العام الميلادي :591"],"text":"وقع حِلفُ الفُضولِ في الشَّهرِ الحرامِ, تَداعتْ إليهِ قبائلُ من قُريشٍ, بَنو هاشمٍ، وبَنو المطَّلبِ، وأسدُ بنُ عبدِ العُزَّى، وزُهْرَةُ بنُ كِلابٍ، وتَيْمُ بنُ مُرَّةَ، فاجتمعوا في دارِ عبدِ الله بنِ جُدْعانَ التَّيميِّ؛ لِسِنِّه وشَرفِه، فتعاقدوا وتعاهدوا على ألَّا يجدوا بمكَّة مظلومًا من أهلِها وغيرِهم من سائرِ النَّاس إلَّا قاموا معه، وكانوا على مَن ظلمهُ حتَّى تُرَدَّ عَليهِ مَظلمتُه، وشهِد هذا الحِلفَ رسولُ الله صلى الله عليه وسلم وقال عنه: (لقد شَهِدتُ في دارِ عبدِ الله بنِ جُدْعانَ حِلفًا ما أحبُّ أنَّ لي بهِ حُمْرَ النَّعَمِ، ولو أُدْعى بهِ في الإسلامِ لأَجبتُ). وهذا الحِلفُ تُنافي رُوحهُ الحَميَّة الجاهليَّة التي كانت العصبيَّة تُثيرها، ويُقال في سببِ هذا الحِلفِ: إنَّ رجلًا من زُبَيْد قَدِم مكَّةَ ببِضاعةٍ، واشتراها منه العاصُ بنُ وائلٍ السَّهميُّ، وحَبس عنه حقَّه، فاستعدى عليهِ الأَحلافَ عبدَ الدَّارِ ومَخزومًا، وجُمَحًا, وسَهْمًا وعَدِيًّا فلم يَكترِثوا له، فَعَلَا جبلَ أبي قُبَيْسٍ، ونادى بأشعارٍ يصِف فيها ظلامتَه رافعًا صوتَه، فمشى في ذلك الزُّبيرُ بنُ عبدِ المطَّلب، وقال: ما لهذا مَتْرَكٌ. حتَّى اجتمعوا فعقدوا الحِلفَ الذي عُرف بحِلفِ الفُضولِ, ثمَّ قاموا إلى العاصِ بنِ وائلٍ فانتزعوا منه حَقَّ الزُّبيديِّ. وسببُ تَسميتِه بهذا الاسمِ: أنَّ ثلاثةً من قبيلةِ جُرْهُمَ هُم: الفضلُ بنُ فَضالةَ، والفضلُ بنُ وَداعةَ، والفضلُ بنُ الحارثِ؛ قد عقدوا قديمًا نظيرًا لهذه المُعاهدةِ، فلمَّا أَشبهَ فعلُ القُريشيِّين فعلَ هؤلاء الجُرهُميِّين الأُوَلِ المُسَمَّوْنَ جميعًا بالفضلِ سُمِّيَ الحِلفُ: حِلفُ الفُضولِ."},{"id":9,"title":"زَواجُ النَّبيِّ صلَّى الله عَليهِ وسلَّم من خَديجةَ بنتِ خُويلدٍ رضِي الله عنها .","date":["العام الهجري :28ق هـ","العام الميلادي :595"],"text":"اختلفتْ الأقوالُ في عُمُرِ النَّبيِّ صلى الله عليه وسلم وعُمُرِ خَديجةَ حين زَواجهِما، فقِيل: كان خمسًا وعِشرين. وقِيل: سبعًا وعِشرين. وقِيل: ثلاثين. وقِيل: غيرَ ذلك، وأمَّا عُمُرُ خَديجةَ فكذلك تضاربتِ الأقوالُ بين خمسٍ وثلاثين وأربعين وغيرِ ذلك، لمَّا سمِعتْ خَديجةُ رضي الله عنها بالنَّبيِّ صلى الله عليه وسلم وبأمانتِه و أخلاقِه الكريمةِ، فقد جاء في رِوايةٍ: أنَّ أُختَ خَديجةَ قد اسْتَكْرَتْ رسولَ الله صلى الله عليه وسلم وشَريكَه، فلمَّا قَضَوْا السَّفرَ بقِي لهم عليها شيءٌ، فجعل شَريكُه يأتيهِم ويتقاضاهُم، ويقولُ لمحمَّدٍ (صلى الله عليه وسلم): انطلقْ. فيقولُ: اذهبْ أنت، فإنِّي أستحيي. فقالتْ مَرَّةً -وقد أتاهُم شَريكُه-: أين محمَّدٌ لا يجيءُ معك؟ قال: قد قلتُ له، فزعَم أنَّه يَستحيي، فذكرتْ ذلك لأختِها خَديجةَ، فقالتْ: ما رأيتُ رجلًا قَطُّ أشدَّ حياءً، ولا أَعَفَّ ولا......من محمَّدٍ (صلى الله عليه وسلم). فوقع في نَفْسِ أختِها خَديجةَ، فبعثتْ إليهِ، فقالتْ: ائْتِ أبي فاخطُبْ إليهِ. فقال: أبوكِ رجلٌ كثيرُ المالِ وهو لا يفعلُ. قالتْ: انطلقْ فالقِه وكَلِّمْهُ، ثمَّ أنا أَكفيكَ. وقد تزوَّجها النَّبيُّ صلى الله عليه وسلم وهي ثَيِّبٌ."},{"id":10,"title":"سفر النبي صلَّى اللهُ عليه وسلَّم للمرة الثانية إلى الشام .","date":["العام الهجري :28ق هـ","الشهر القمري : ذي الحجة","العام الميلادي :596"],"text":"لمَّا بلغَ رسولُ الله صلَّى اللهُ عليه وسلَّم خَمسًا وعِشرين سنةً وليس له بمكَّةَ اسمٌ إلا \"الأمينُ\"؛ لِمَا تكامَلَ فيه من خِصال الخير، قال له عمُّه أبو طالِبٍ: \"يا ابنَ أخي، أنا رجلٌ لا مالَ لي، وقد اشتَدَّ الزَّمانُ علينا، وألَحَّت علينا سِنونَ مُنكَرةٌ، وليس لنا مادَّةٌ ولا تجارةٌ، وهذه عيرُ قومِك قد حَضَرَ خروجُها إلى الشامِ، وخديجةُ بِنتُ خوَيلدٍ تبعَثُ رِجالًا من قومِك في عيرانِها، فيتَّجِرون لها في مالِها، ويُصيبون مَنافِعَ، فلو جِئتَها فوَضَعْتَ نفسَك عليها لأسرَعَت إليك، وفَضَّلَتْكَ على غيرِك، لِمَا يبلُغُها عنك من طهارَتِك، وإن كنتُ لَأكرَهُ أن تأتيَ الشامَ، وأخافُ عليك من يهودَ، ولكن لا نَجِدُ من ذلك بُدًّا\".وكانتْ خديجةُ بِنتُ خوَيلدٍ امرأةً تاجرةً ذاتَ شرفٍ ومالٍ كثيرٍ وتجارةٍ تبعَثُ بها إلى الشَّامِ، فتكونُ عِيرُها كعامَّةِ عِيرِ قُرَيشٍ، وكانت تستأجِرُ الرِّجالَ وتدفَعُ إليهمُ المالَ مُضاربةً، وبلغ خَديجةَ ما كان من صِدقِ حديثِ النبيِّ صلَّى اللهُ عليه وسلَّم وعِظَمِ أمانَتِه، وكرمِ أخلاقِه، فأرسلَتْه في تجارَتِها، فخَرَج مع غُلامِها مَيسَرةَ حتى قدِمَ الشامَ، وجعل عُمومَتُه يوصون به أهلَ العيرِ حتى قدِمَ الشامَ، فنَزَلَا في سوقِ بُصرَى في ظلِّ شجرةٍ قريبًا من صَومعةِ راهِبٍ يُقال له: نِسْطُورَا، فاطَّلَع الرَّاهبُ إلى مَيسَرةَ -وكان يعرِفُه-؛ فقال: \"يا مَيسَرةُ، مَن هذا الذي نزَل تحتَ هذه الشجرةِ؟\"، فقال مَيسَرةُ: \"رجلٌ من قريش من أهلِ الحرمِ\". فقال له الرَّاهبُ: \"ما نَزَل تحتَ هذه الشجرةِ إلا نبيٌّ\".ثم باع رسول الله صلَّى اللهُ عليه وسلَّم سِلعتَه -يعني: تِجارَتَه- التي خَرَج بها، واشترى ما أراد أن يشتريَ، ثم أقبل قافِلًا إلى مكةَ ومعه مَيسَرةُ؛ فلما قدِمَ مكةَ على خديجةَ بمالِها باعت ما جاء به بأضعَفَ أو قريبًا، وحدَّثها مَيسَرةُ عن قَولِ الراهبِ، وما رَأى من شأنِ النبيِّ صلَّى اللهُ عليه وسلَّم، فعَرَضَت نَفسَها عليه رَضي اللهُ عنها، وكانتْ أوسَطَ نساءِ قُريشٍ نَسَبًا وأعظمَهُنَّ شَرَفًا، وأكثَرَهُنَّ مالًا، فلمَّا قالت ذلك لرسولِ الله صلَّى اللهُ عليه وسلَّم ذَكَر ذلك لأعمامِه، فخرج معه عمُّه حمزةُ حتى دَخَل على خويلِدِ بنِ أسَدٍ فخَطَبها إليه، فتزوَّجها النبيُّ صلَّى اللهُ عليه وسلَّم، وكانتْ أوَّلَ امرأةٍ تزوَّجَها، ولم يتزوَّج عليها غيرَها حتى ماتت رَضي اللهُ عنها."},{"id":11,"title":"النَّبيُّ صلَّى الله عَليهِ وسلَّم يضعُ الحَجَرَ الأَسودَ في مكانِه في الكعبةِ .","date":["العام الهجري :18ق هـ","العام الميلادي :605"],"text":"عن مُجاهدٍ، عن مَولاهُ أنَّه حدَّثه: أنَّه كان فيمن يَبني الكعبةَ في الجاهليَّةِ... قال: فَبَنَيْنا حتَّى بلغنا موضعَ الحَجَرِ وما يَرى الحَجَرَ أحدٌ، فإذا هو وَسْطَ حِجارتِنا مِثلَ رأسِ الرَّجلِ، يَكادُ يَتراءى منه وجهُ الرَّجلِ، فقال بطنٌ من قُريشٍ: نحن نَضعهُ. وقال آخرون: نحن نَضعهُ. فقالوا: اجعلوا بينكم حَكَمًا. قالوا: أوَّلُ رجلٍ يَطلُعُ مِنَ الفَجِّ. فجاء النَّبيُّ صلى الله عليه وسلم، فقالوا: أتاكمُ الأَمينُ. فقالوا له، فوضعهُ في ثوبٍ ثمَّ دعا بُطونَهم فأخذوا بنواحيه معهُ، فوضعهُ هو صلَّى الله عَليهِ وسلَّم."},{"id":12,"title":"أوَّلُ نُزولِ الوَحيِ ونُبوءةُ النَّبيِّ صلَّى الله عَليهِ وسلَّم .","date":["العام الهجري :13ق هـ","الشهر القمري : رمضان","العام الميلادي :610"],"text":"كان أوَّلَ ما بُدِئ بهِ الوحيُ هو الرُّؤيا الصَّادقةُ في النَّومِ، وكان لا يَرى رُؤيا إلا جاءتْ مِثلَ فَلَقِ الصُّبحِ، ثمَّ إنَّه صلى الله عليه وسلم حُبِّبَ إليهِ الخَلاءُ، فكان يَخلو في غارِ حِراءٍ ويَتَحَنَّثُ فيهِ مُتعبِّدًا، حتَّى جاءهُ جبريلُ عَليهِ السَّلامُ وهو في الغارِ بقولِه تعالى: {اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ (1) خَلَقَ الْإِنْسَانَ مِنْ عَلَقٍ (2) اقْرَأْ وَرَبُّكَ الْأَكْرَمُ (3) الَّذِي عَلَّمَ بِالْقَلَمِ (4) عَلَّمَ الْإِنْسَانَ مَا لَمْ يَعْلَمْ (5) } [العلق: 1 - 6]. فَقَصَّ ذلك على زوجتِه خَديجةَ التي قَصَّتْ ما حدث على وَرقةَ بنِ نَوفلٍ فصدَّقهُ، وقال: إنَّه النَّاموسُ الأكبرُ الذي جاء موسى، ثمَّ انقطع الوحيُ فَترةً مِنَ الزَّمنِ، ثمَّ عاد إليهِ جبريلُ وهو قاعدٌ على كُرسيٍّ، فخاف منه النَّبيُّ صلى الله عليه وسلم ورجع إلى أهلِه قائلًا: زَمِّلوني زَمِّلوني. فأنزل الله تعالى: {يَاأَيُّهَا الْمُدَّثِّرُ (1) قُمْ فَأَنْذِرْ (2) وَرَبَّكَ فَكَبِّرْ (3) وَثِيَابَكَ فَطَهِّرْ (4) وَالرُّجْزَ فَاهْجُرْ (5)} [المدثر: 1 - 5]. فكان ذلك أوَّلَ النُّبوَّةِ والأمرَ بالتَّبليغِ."},{"id":13,"title":"فُتورُ الوحيِ عن رسولِ الله صلَّى الله عَليهِ وسلَّم .","date":["العام الهجري :13ق هـ","الشهر القمري : شوال","العام الميلادي :610"],"text":"فَتَرَ الوحيُ عن رسولِ الله صلى الله عليه وسلم فَترةً مِنَ الزَّمنِ, حتَّى شَقَّ ذلك عَليهِ فأحزنهُ، فجاءهُ جبريلُ بسورةِ الضُّحى يُقسِمُ له رَبُّهُ -وهو الذي أكرمهُ بما أكرمهُ بهِ- ما وَدَعَهُ, فقد روى البخاري في صحيحه من حديث جندب بن عبدالله رضي الله عنه قال: احْتَبَسَ جِبْرِيلُ صَلَّى اللهُ عليه وسلَّمَ علَى النبيِّ صَلَّى اللهُ عليه وسلَّمَ، فَقالتِ امْرَأَةٌ مِن قُرَيْشٍ -وهي أمُّ جميلٍ أَرْوى بنتُ حَرْبٍ أُخْتُ أبي سُفيانَ وزوجُ أبي لَهَبٍ-: أَبْطَأَ عليه شيطَانُهُ، فَنَزَلَتْ: {وَالضُّحَى واللَّيْلِ إذَا سَجَى، ما ودَّعَكَ رَبُّكَ وما قَلَى}."},{"id":14,"title":"أوَّلُ النَّاسِ إيمانًا بالله ورسولِه .","date":["العام الهجري :13ق هـ","الشهر القمري : شوال","العام الميلادي :610"],"text":"كان أوَّلَ مَنْ آمنَ بالله ورسولِه خَديجةُ بنتُ خويلدٍ زوجتُه صلى الله عليه وسلم، وأبو بكرٍ الصِّدِّيقُ، وعليُّ بنُ أبي طالبٍ، ثمَّ أَسلمَ زيدُ بنُ حارثةَ مولى رسولِ الله صلى الله عليه وسلم. وقد أَسلمَ بدُعاءِ أبي بكرٍ الصِّدِّيقِ عُثمانُ بنُ عفَّانَ، والزُّبيرُ بنُ العوَّامِ، وسعدُ بنُ أبي وقَّاصٍ، وطَلحةُ بنُ عُبيدِ الله، وعبدُ الرَّحمنِ بنُ عوفٍ, ثمَّ أَسلمَ أبو عُبيدةَ بنُ الجرَّاحِ، وأبو سَلمةَ بنُ عبدِ الأَسدِ، وعُثمانُ بنُ مَظعونٍ، ثمَّ أَخواهُ قُدامةُ وعبدُ الله، وابنُه السَّائبُ بنُ عُثمانَ بنِ مَظعونٍ، وأسماءُ بنتُ أبي بكرٍ الصِّدِّيقِ، وعائشةُ بنتُ أبي بكرٍ الصِّدِّيقِ، وهي صغيرةٌ، ثمَّ أسلمَ خالدُ بنُ سعيدِ بنِ العاصي، وأسلمتْ معه امرأتُه أُمَيْنَةُ بن بنتُ خلفِ بنِ أَسعدَ الخُزاعيَّةُ، وبلالٌ، وعمَّارُ بنُ ياسرٍ، وأمُّهُ سُميَّةُ، وصُهيبُ بنُ سِنانٍ النَّمَريُّ المعروف بالرُّوميِّ، وعَمرُو بنُ عَبَسةَ السُّلميُّ، وعَمرُو بنُ سعيدِ بنِ العاصي، وسعيدُ بنُ زيدِ بنِ عَمرو بنِ نُفيلٍ، وزوجتُه فاطمةُ بنتُ الخطَّابِ أختُ عُمرَ بنِ الخطَّابِ، وعُميرُ بنُ أبي وقَّاصٍ، وعبدُ الله بنُ مَسعودٍ، وأخوهُ عُتبةُ بنُ مَسعودٍ، وسَليطُ بنُ عمرٍو العامريُّ، وعيَّاشُ بنُ أبي رَبيعةَ المخزوميُّ، وامرأتُه أسماءُ بنتُ سَلامةَ بن مُخَرِّبَةَ التَّميميَّةُ، ومَسعودُ بنُ رَبيعةَ بنِ عَمرٍو القاريُّ من بني الهُونِ بنِ خُزيمةَ، وهُم القارَةُ، وخُنَيْسُ بنُ حُذافةَ بنِ قَيسِ بنِ عَدِيٍّ السَّهميُّ، وعبدُ الله جَحشٍ الأسَديُّ, تَتِمَّةُ السَّابقين إلى الإيمانِ برسولِ الله صلى الله عليه وسلم: وجعفرُ بنُ أبي طالبٍ، وامرأتُه أسماءُ بنتُ عُميسٍ، وعامرُ بنُ رَبيعةَ العَنَزيُّ، من عَنْزِ بنِ وائلٍ، حَليفُ الخطَّابِ بنِ نُفيلٍ، وأبو أحمدَ بنُ جَحشٍ الأعمى، وحاطبُ بنُ الحارثِ بنِ مَعمرٍ الجُمَحيُّ، وامرأتُه بنتُ المُجَلِّلِ العامريَّةُ، وحطَّابُ بنُ الحارثِ أخوهُ، وامرأتُه فكهية فُكَيْهَةُ بنتُ يَسارٍ، وأخوهما مَعمرُ بنُ الحارثِ بنِ مَعمرٍ الجُمَحيُّ، والمُطَّلِبُ بنُ أَزهرَ بنِ عبدِ عَوفٍ الزُّهريُّ، وامرأتُه رَمْلَةُ بنتُ أبي عَوفٍ السَّهميَّةُ، والنَّحَّامُ واسمُه نُعيمُ بنُ عبدِ الله العَدويُّ، وعامرُ بنُ فُهيرةَ مولًى لأبي بكرٍ الصِّدِّيق، وحاطبُ بنُ عَمرِو بنِ شمسِ بنِ عبدِ وُدٍّ العامريُّ أخو سَليطِ بنِ عَمرٍو، وأبو حُذيفةُ بنُ عُتبةَ بنِ رَبيعةَ، واسمُه مِهْشَمُ بنُ عُتبةَ..."},{"id":15,"title":"ما لقِي الصَّحابةُ من إيذاءِ قُريشٍ .","date":["العام الهجري :9ق هـ","العام الميلادي :613"],"text":"كان أوَّلَ مَن أظهرَ إسلامَه سبعةٌ: رسولُ الله صلى الله عليه وسلم، وأبو بكرٍ، وعمَّارٌ، وأمُّهُ سُميَّةُ، وصُهيبٌ، وبلالٌ، والمقدادُ، فأمَّا رسولُ الله صلى الله عليه وسلم فمنعهُ الله بعمِّه أبي طالبٍ، وأمَّا أبو بكرٍ فمنعهُ بقومِه، وأما سائرهُم فأخذهُم المشركون فألبسوهُم أَدراعَ الحديدِ وصَهروهُم في الشَّمسِ، فما منهُم إلَّا مَن واتاهُم فيما أرادوا وأَوْهَمهُم بذلك إلَّا بلالًا، فإنَّه هانتْ عَليهِ نفسُه في الله عزَّ وجلَّ، وهان على قومِه فأخذوه، وأعطوه الوِلدانَ، فجعلوا يطوفون به في شِعابِ مكَّة، وهو يقولُ: أَحَدٌ، أَحَدٌ. فجعلوا في عُنقهِ حبلًا، ودفعوه إلى الصِّبيانِ يلعبون بهِ، حتَّى أثَّر في عُنقهِ، وكان بلالٌ لبعضِ بني جُمَحٍ، وكان الذي يتولَّى كِبْرَ تَعذيبهِ أُميَّةُ بنُ خَلفٍ، فكان يُخرجهُ إذا حَمِيَتِ الظَّهيرةُ، فيَطرَحهُ على ظَهرهِ في بَطحاءِ مكَّة، ثمَّ يأمرُ بالصَّخرةِ العظيمةِ فتوضعُ على صدرهِ. ثمَّ يقولُ له: لا تزالُ هكذا حتَّى تموتَ أو تكفرَ بمحمَّدٍ وتعبدَ اللَّاتَ والعُزَّي. فيقولُ وهو في هذا العذابِ والبلاءِ: أَحَدٌ أَحَدٌ. وكأنَّما كان يزيدُه عذابُه وبلاؤُه إيمانًا فوق إيمانٍ، ورقَّ له أبو بكرٍ حين رآهُ يومًا في هذا الهوانِ الشَّديدِ، فاشتراهُ وأعتقهُ، وأعتقَ معه سِتًّا ممَّن كانوا يُعذَّبون على الإسلامِ."},{"id":16,"title":"طلب قريش من أبي طالب أن يكف عنهم رسول الله صلى الله عليه وسلم .","date":["العام الهجري :9ق هـ","العام الميلادي :613"],"text":"كان رسولُ الله صلَّى اللهُ عليه وسلَّم يدْعو إلى الله تعالى في كُلِّ أحوالِهِ؛ ليلًا ونهارًا، وسِرًّا وجهرًا، لا يَصرِفُه عن ذلك صارِفٌ ولا يَرُدُّه عن ذلك رادٌّ، ولا يَصُدُّه عن ذلك صادٌّ، يَتبَعُ الناسَ في أنديَتِهم، ومَجامِعِهم ومَحافِلِهم وفي المَواسمِ، ومَواقفِ الحَجِّ؛ يدعو مَن لَقيَه مِن حرٍّ وعبدٍ، وضعيفٍ وقويٍّ، وغنيٍّ وفقيرٍ.وتسلَّط عليه وعلى مَنِ اتَّبَعه كفارُ قَومِه من مُشرِكي قُريشٍ، بل كان من أشدِّ الناسِ عليه عمُّه أبو لَهَبٍ وامرأتُه أُمُّ جَميلٍ حَمَّالةُ الحَطَبِ -أرْوَى بِنتُ حَربِ بن أُمَيَّةَ أختُ أبي سُفيانَ-، وكان عمُّه أبو طالبِ بن عبد المُطَّلب يحنو عليه، ويُحسِنُ إليه، ويُدافِعُ عنه ويُحامي، ويُخالِفُ قَومَه في ذلك؛ مع أنه على دِينِهم، وكان استِمرارُه على دينِ قَومِه من حكمةِ الله تعالى، ومَّما صَنَعه لرَسولِه من الحِمايةِ؛ إذ لو كان أسلَمَ أبو طالب لَمَا كان له عند مُشرِكي قُريشٍ وَجاهةٌ ولا كلمةٌ، ولا كانوا يَهابونه ويَحتَرِمونَه.روى أصحاب السِّير أنَّ قريشًا جاءتْ إلى أبي طالبٍ فقالوا: \"إنَّ ابنَ أخيك هذا قد آذانا في نادينا ومَسجِدِنا فانْهَهُ عنَّا\". فقال: \"يا عَقيلُ، انطلِقْ فأْتِني بمُحمَّدٍ\"، فجاء به في الظَّهيرةِ في شدَّةِ الحَرِّ. فلمَّا أتاهم قال: \"إنَّ بني عمِّك هؤلاء زعموا أنَّك تُؤذيهم في ناديهم ومَسجدِهم؛ فانتَهِ عن أذاهم\"، فحلَّق رسولُ الله صلَّى اللهُ عليه وسلَّم ببصرِه إلى السماءِ؛ فقال: \"تَرَونَ هذه الشَّمسَ؟\" قالوا: \"نعم\"، قال: \"فما أنا بأقدَرَ أن أدَعَ ذلك منكم على أن تَشتَعِلوا منها بشُعلةٍ\". فقال أبو طالبٍ: \"واللهِ ما كَذَب ابنُ أخي قطُّ فارجِعوا\"."},{"id":17,"title":"الهِجرةُ الأُولى إلى الحَبشةِ .","date":["العام الهجري :8ق هـ","الشهر القمري : رجب","العام الميلادي :615"],"text":"قالتْ أمُّ سَلمةَ رضي الله عنها: لمَّا ضاقتْ علينا مكَّة، وأوذِيَ أصحابُ رسولِ الله صلى الله عليه وسلم وفُتنوا، ورَأَوْا ما يُصيبهُم مِنَ البلاءِ والفِتنةِ في دينهِم، وأنَّ رسولَ الله صلى الله عليه وسلم لا يستطيعُ دفعَ ذلك عنهُم، وكان رسولُ الله صلى الله عليه وسلم في مَنَعَةٍ من قومهِ وعمِّه، لا يَصِلُ إليه شيءٌ ممَّا يَكرهُ ممَّا ينالُ أصحابَه، فقال لهم رسولُ الله صلى الله عليه وسلم: إنَّ بأرضِ الحَبشةِ مَلِكًا لا يُظلمُ عنده، فالحقوا ببلادهِ حتَّى يجعلَ الله لكم فَرَجًا ومَخرجًا ممَّا أنتم فيهِ. فخرجنا إليها حتَّى اجتمعنا بها، فنزلنا بخيرِ دارٍ إلى خيرِ جارٍ، أَمَّنَّا على ديننا، ولم نخشَ منه ظُلمًا.... وقيل: كان مخرجهُم إلى الحَبشةِ في رجبٍ في السَّنةِ الخامسةِ مِنَ البِعثةِ النَّبويَّةِ. هاجر مِنَ المسلمين فيها اثنا عشرَ رجلًا، وأربعُ نِسوةٍ، منهم عُثمانُ بنُ عفَّانَ، وهو أوَّلُ من خرج ومعه زوجتُه رُقيَّةُ بنتُ رسولِ الله صلى الله عليه وسلم."},{"id":18,"title":"إسلام حمزة بن عبد المطلب رَضي اللهُ عنه .","date":["العام الهجري :7ق هـ","العام الميلادي :615"],"text":"في أواخِرِ السنةِ السَّادسةِ من النُّبوَّةِ أسلم حَمزةُ بنُ عبد المطلب رَضي اللهُ عنه. وسببُ إسلامِه: أنَّ أبا جَهلٍ مرَّ برسولِ الله صلَّى اللهُ عليه وسلَّم يومًا عند الصَّفا، فآذاه ونال منه، ورسولُ الله صلَّى اللهُ عليه وسلَّم ساكِتٌ لا يُكلِّمُه، ثم ضَرَبه أبو جَهلٍ بحَجَرٍ في رأسِه فشَجَّه حتى نَزَف منه الدَّمُ، ثم انصَرَف عنه إلى نادي قُرَيشٍ عند الكعبةِ فجَلَس معهم، وكانت مولاةٌ لعَبدِ الله بنِ جُدعانَ في مَسكَنٍ لها على الصَّفا ترى ذلك، وأقبل حَمزةُ من القَنْصِ مُتَوَشِّحًا قَوسَه، فأخبَرَتْه المَولاةُ بما رأتْ من أبي جَهلٍ، فغَضِب حَمزةُ وخرَج يسعى، لم يقِفْ لأحدٍ، مُعِدًّا لأبي جهلٍ إذا لَقيَه أن يوقِعَ به، فلمَّا دَخَل المسجِدَ قام على رأسِه وقال له: \"تَشتُمُ ابنَ أخي وأنا على دِينِه!\"، ثم ضَرَبه بالقَوسِ فشَجَّه شجَّةً مُنكرةً، فثار رجالٌ من بني مخزومٍ -حيِّ أبي جهلٍ- وثار بنو هاشمٍ -حيِّ حمزةَ- فقال أبو جهلٍ: \"دَعوا أبا عِمارةَ! فإنِّي سَبَبتُ ابنَ أخيه سبًّا قبيحًا\".وقال ابنُ إسحاقَ: \"ثم رَجَع حمزةُ إلى بيتِه فأتاه الشَّيطانُ فقال: أنت سيِّدُ قُريشٍ اتبعْتَ هذا الصابِئَ، وتركتَ دينَ آبائك، لَلموتُ خيرٌ لك ممَّا صنعتَ. فأقبلَ حَمزةُ على نفسِه وقال: \"ما صنعتُ؟! اللَّهمَّ إن كان رُشدًا فاجعَلْ تَصديقَه في قلبي، وإلَّا فاجعَل لي ممَّا وَقعتُ فيه مَخرجًا\"، فبات بلَيلةٍ لم يَبِتْ بِمِثلها مِن وَسوسةِ الشَّيطانِ، حتَّى أصبَحَ فغَدا على رسولِ الله صلَّى اللهُ عليه وسلَّم، فقال: \"يا بن أخي، إنِّي قد وَقعتُ في أمرٍ ولا أعرِفُ المَخرجَ منه، وإقامةُ مِثلي على ما لا أدري ما هو، أرُشْدٌ أم هو غَيٌّ شَديدٌ؟ فحدِّثني حديثًا؛ فقدِ اشتَهيتُ يا بنَ أخي أن تُحدِّثَني، فأقبل رسولُ الله صلَّى اللهُ عليه وسلَّم فذكَّره ووَعَظه، وخوَّفَه وبَشَّرَه، فألقَى اللهُ في قلبِه الإيمانَ بما قال رسولُ الله صلَّى اللهُ عليه وسلَّم. فقال: \"أشهَدُ أنَّك الصَّادِقُ شهادةَ الصِّدقِ، فأظهِرْ يا بن أخي دينَكَ، فواللهِ ما أُحِبُّ أنَّ لي ما أظلَّتْه السماءُ وأنِّي على ديني الأوَّلِ\"؛ فكان إسلامُ حمزةَ رَضي اللهُ عنه أوَّلَ الأمرِ أنَفةَ رجلٍ أبَى أن يُهانَ مَولاهُ، ثم شَرَح اللهُ صدرَهُ، فاسْتمَسْكَ بالعُروةِ الوُثقى، واعتَزَّ به المُسلِمون أيَّما اعتِزازٍ!"},{"id":19,"title":"الهِجرةُ الثَّانيةُ إلى الحَبشةِ .","date":["العام الهجري :7ق هـ","العام الميلادي :615"],"text":"بلغ المهاجرين في الحَبشةِ أنَّ قُريشًا قد أسلمتْ، فرجعوا إلى مكَّة في شوَّالٍ من نفسِ السَّنةِ التي هاجروا فيها، فلمَّا كانوا دون مكَّة ساعةً من نهارٍ وعرفوا جلية الأمرِ رجع منهم مَنْ رجع إلى الحَبشةِ، ولم يدخلْ في مكَّة مِن سائرهِم أحدٌ إلَّا مُستخفِيًا، أو في جِوارِ رجلٍ من قُريشٍ‏.‏ ثم اشتدَّ عليهِم وعلى المسلمين البلاءُ والعذابُ من قُريشٍ، وسَطَتْ بهِم عشائرُهُم، فقد كان صعبًا على قُريشٍ ما بلغها عَنِ النَّجاشيِّ من حُسنِ الجِوارِ، ولم يرَ رسولُ الله صلى الله عليه وسلم بُدًّا من أن يُشيرَ على أصحابهِ بالهجرةِ إلى الحَبشةِ مَرَّةً أُخرى‏.‏ واستعدَّ المسلمون للهجرةِ مَرَّةً أُخرى، حاولتْ قُريشٌ إحباطَ عمليَّةِ الهجرةِ الثَّانيةِ بَيْدَ أنَّ المسلمين كانوا أسرعَ، فانحازوا إلى نَجاشيِّ الحَبشةِ قبلَ أن يُدركوا‏.‏ هاجر مِنَ الرِّجالِ ثلاثةٌ وثمانون رجلًا، وثماني عشرةَ أو تسعَ عشرةَ امرأةً. فأرسلتْ قُريشٌ عَمرَو بنَ العاصِ، وعبدَ الله بنَ أبي رَبيعةَ قبلَ أن يُسلِما، وأرسلوا معهُما الهدايا المُستطرَفةَ للنَّجاشيِّ ولبَطارِقتِهِ، وبعد أن حضرا إلى النَّجاشيِّ قدَّما له الهدايا، ثمَّ كلَّماهُ فقالا له‏:‏ أيُّها الملكُ، إنَّه قد ضَوَى إلى بلدِك غِلمانٌ سُفهاءُ، فارقوا دينَ قومهِم، ولم يدخلوا في دينِك، وجاءوا بدينٍ ابتدعوه، لا نعرفُه نحن ولا أنت، وقد بعثَنا إليك فيهِم أشرافُ قومهِم من آبائهِم وأعمامهِم وعشائرهِم؛ لِتردَّهُم إليهِم، فَهُمْ أعلى بهِم عينًا، وأعلمُ بما عابوا عليهِم. وعاتبوهُم فيهِ،‏ وقالت البَطارِقةُ‏:‏ صَدقا أيُّها الملكُ، فأسلِمْهُم إليهِما، فليردَّاهُم إلى قومهِم وبلادهِم‏.‏ فأرسل النَّجاشيُّ إلى المسلمين، ودعاهُم، فحضروا، وكانوا قد أجمعوا على الصِّدقِ كائنًا ما كان،‏ فقال لهم النَّجاشيُّ‏:‏ ما هذا الدِّينُ الذي فارقتُم فيه قومَكُم، ولم تدخلوا به في ديني ولا دينِ أحدٍ من هذه المِلَلِ ‏؟‏ قال جعفرُ بنُ أبي طالبٍ -وكان هو المُتكلِّمُ عَنِ المسلمين‏:‏ أيُّها الملكُ، كُنَّا قومًا أهلَ جاهليَّةٍ؛ نعبدُ الأصنامَ، ونأكلُ المَيتةَ، ونأتي الفواحشَ، ونقطعُ الأرحامَ، ونُسِئُ الجِوارَ، ويأكلُ مِنَّا القويُّ الضَّعيفَ، وعدَّد له مَحاسنَ ما جاءهُم به صلى الله عليه وسلم، ثمَّ قال: فصدَّقناهُ، وآمنَّا بهِ، واتَّبعناهُ على ما جاءنا بهِ من دينِ الله، فعبدنا الله وحدَه، فلم نُشركْ به شيئًا، وحرَّمنا ما حُرِّمَ علينا، وأحللنا ما أحلَّ لنا، فعدا علينا قومُنا، فعذَّبونا وفَتنونا عن ديننا؛ لِيردُّونا إلى عِبادةِ الأوثانِ من عِبادةِ الله تعالى، وأن نَستحِلَّ ما كُنَّا نَستحِلُّ مِنَ الخبائثِ، فلمَّا قَهرونا وظَلمونا وضيَّقوا علينا، وحالوا بيننا وبين ديننا خرجنا إلى بلادِك، واخترناك على مَنْ سِواكَ، ورغِبنا في جِوارِك، ورَجوْنا ألَّا نُظْلَمَ عندك أيُّها الملكُ‏.‏ فقال له النَّجاشيُّ‏:‏ هل معك ممَّا جاء به عن الله من شيءٍ‏؟‏ فقال له جعفرٌ‏:‏ نعم‏.‏ فقال له النَّجاشيُّ‏:‏ فاقْرأْهُ عليَّ، فقرأ عَليهِ صدرًا من: (سورة مريم) فبكى النَّجاشيُّ حتَّى اخْضَلَّتْ لِحيتُه، وبكتْ أساقِفتُه حتَّى أخْضَلُوا مصاحِفَهُم حين سمِعوا ما تلا عليهِم، ثمَّ قال لهم النَّجاشيُّ‏:‏ إنَّ هذا والذي جاء به عيسى لَيخرجُ من مِشكاةٍ واحدةٍ، انطلقا، فلا والله لا أُسلِمُهُم إليكُما، ولا يُكادونَ -يُخاطِبُ عَمرَو بنَ العاصِ وصاحبَه- فخرجا، فلمَّا خرجا قال عَمرُو بنُ العاصِ لعبدِ الله بنِ أبي رَبيعةَ‏:‏ والله لآتينَّهُ غدًا عنهُم بما أَسْتَأْصِلُ به خَضراءَهُم‏.‏ فقال له عبدُ الله بنُ أبي رَبيعةَ‏:‏ لا تفعلْ، فإنَّ لهم أرحامًا، وإنْ كانوا قد خالفونا. ولكنْ أصرَّ عَمرٌو على رأيِهِ‏.‏ فلمَّا كان الغدُ قال للنَّجاشيِّ‏:‏ أيُّها الملكُ، إنَّهم يقولون في عيسى ابنِ مريمَ قولًا عظيمًا، فأرسل إليهم النَّجاشيُّ يسألهُم عن قولِهم في المَسيحِ ففَزِعوا، ولكنْ أجمعوا على الصِّدقِ، كائنًا ما كان، فلمَّا دخلوا عَليهِ وسألهم، قال له جعفرٌ‏:‏ نقولُ فيه الذي جاءنا به نبيُّنا صلى الله عليه وسلم‏:‏ هو عبدُ الله ورسولُه ورُوحهُ وكَلِمتُه ألقاها إلى مريمَ العذراءِ البَتُولِ‏.‏ فأخذ النَّجاشيُّ عودًا مِنَ الأرضِ ثمَّ قال‏:‏ والله ما عَدا عيسى ابنُ مريمَ ما قلتَ هذا العودَ. فتَناخَرتْ بَطارِقتُه، فقال‏:‏ وإنْ نَخَرْتُم ‏.‏ ثمَّ قال للمسلمين‏:‏ اذهبوا فأنتم شُيُومٌ بأرضي -والشُّيومُ‏:‏ الآمِنونَ بلسانِ الحَبشةِ- مَنْ سَبَّكم غَرِم، مَنْ سَبَّكم غَرِم، مَنْ سَبَّكم غَرِم، ما أُحِبُّ أنَّ لي دَبْرًا من ذهبٍ وإنِّي آذيتُ رجلًا منكُم -والدَّبْرُ‏:‏ الجبلُ بلسانِ الحَبشةِ-‏ ثمَّ قال لِحاشِيَتِهِ‏:‏ رُدُّوا عليهِما هَداياهُما فلا حاجةَ لي بها، فوالله ما أخذَ الله مِنِّـي الرِّشـوةَ حين رَدَّ عليَّ مُلكي، فآخذُ الرِّشـوةَ فيــه، وما أطاع النَّاسَ فِيَّ فأُطيعَـهُم فيهِ‏.‏ قالتْ أمُّ سَلمةَ: فخرجا من عندِه مَقبوحينَ مَردودًا عليهِما ما جاءا بهِ، وأقمنا عندهُ بخيرِ دارٍ مع خيرِ جارٍ‏.‏"},{"id":20,"title":"إِسلامُ عُمَرَ رضِي الله عنهُ .","date":["العام الهجري :7ق هـ","الشهر القمري : ذي الحجة","العام الميلادي :616"],"text":"أخرج الترمذي في سننه عن عبدالله بن عمر رضي الله عنهما أنَّ رسول الله صلى الله عليه وسلم قال: ((اللهم أَعِزَّ الإسلامَ بأَحَبِّ هذين الرجُلَيْنِ إليك بأبي جهلٍ أو بعمرَ بنِ الخطابِ قال وكان أَحَبَّهُما إليه عمرُ)) وروى أهل السِّير أنَّ عمر خرج يومًا مُتوشِّحًا سَيفَهُ يُريدُ القضاءَ على النَّبيِّ صلى الله عليه وسلم، فلقِيهُ رجلٌ فقال: أين تعمدُ يا عُمَرُ؟ قال: أريدُ أنْ أقتُلَ محمَّدًا. قال: كيف تأمنُ من بني هاشمٍ ومن بني زُهرةَ وقد قتلتَ محمَّدًا؟ فقال له عُمَرُ: ما أراك إلَّا قد صَبَوْتَ، وتركتَ دينَك الذي كنتَ عَليهِ، قال: أفلا أدُلُّك على العَجَبِ يا عُمَرُ? إنَّ أُختَك وخَتَنَكَ قد صَبَوَا، وتركا دينَك الذي أنت عَليهِ، فمشى عُمَرُ إليهِما، وعندهُما خَبَّابُ بنُ الأَرَتِّ، معه صَحيفةٌ فيها: سُورةُ [طه] يُقرِئهُما إيَّاها، فلمَّا سمِع خَبَّابٌ حِسَّ عُمَرَ تَوارى في البيتِ، وسَترتْ فاطمةُ أُختُ عُمَرَ الصَّحيفةَ، وكان قد سمِع عُمَرُ حين دنا مِنَ البيتِ قِراءةَ خَبَّابٍ إليهِما، فلمَّا دخل عليهِما قال: ما هذه الهَيْنَمَةُ التي سمعتُها عندكُم؟ فقالا: ما عَدا حديثًا تحدَّثناهُ بيننا. قال: فلَعلَّكُما قد صَبَوْتُما, فقال له خَتَنُهُ: يا عُمَرُ، أرأيتَ إنْ كان الحقُّ في غيرِ دينِك؟ فوثبَ عُمَرُ على خَتَنِهِ فَوَطِئَهُ وَطْئًا شَديدًا, فجاءتْ أختُه فرفعتْهُ عن زَوجِها، فَنَفَحَها نَفْحَةً بيدِه، فَدَمَّى وجهَها، فقالتْ، وهي غَضبى: يا عُمَرُ، إنْ كان الحقُّ في غيرِ دينِك، أشهدُ أنْ لا إلَه إلَّا الله، وأشهدُ أنَّ محمَّدًا رسولُ الله. فلمَّا يَئِسَ عُمَرُ، ورَأى ما بِأُختِه مِنَ الدَّمِ نَدِمَ واستَحْيا، وقال: أَعْطوني هذا الكتابَ الذي عندكُم فأَقرؤهُ، فقالتْ أختُه: إنَّك رِجْسٌ، ولا يَمَسُّهُ إلَّا المُطهَّرون، فقُمْ فاغْتسِلْ، فقام فاغتسَلَ، ثمَّ أخذَ الكتابَ، فقرأَ: بسم الله الرحمن الرحيم فقال: أسماءُ طَيِّبَةٌ طاهرةٌ. ثمَّ قرأَ [طه] حتَّى انتهى إلى قولِه: (إِنَّنِي أَنَا اللَّهُ لَا إِلَهَ إِلَّا أَنَا فَاعْبُدْنِي وَأَقِمِ الصَّلَاةَ لِذِكْرِي) فقال: ما أحسنُ هذا الكلامَ وأَكرمَهُ؟ دِلُّوني على محمَّدٍ. فأتى النَّبيَّ صلى الله عليه وسلم فأَسلمَ عندَه، ثمَّ خرج المسلمون معهُ في صَفَّيْنِ حتَّى دخلوا المسجدَ، فلمَّا رأتهُم قُريشٌ أصابتْها كآبةٌ لم تُصبْها مِثلُها."},{"id":21,"title":"إسلام الطّفيل بن عمرو الدوسي رَضي اللهُ عنه .","date":["العام الهجري :6ق هـ","العام الميلادي :616"],"text":"كانت قُريشٌ تُحذِّر منَ الاستِماعِ للنبيِّ صلَّى اللهُ عليه وسلَّم، فلمَّا قَدِم الطُّفَيلُ بن عمرٍو مكةَ مَشَى إليه رجالٍ من قُرَيشٍ، وكان الطُّفَيلُ رجلًا شَريفًا شاعِرًا لَبيبًا، فقالوا له: \"يا طُفَيلُ، إنَّك قَدِمتَ بلادَنا، وهذا الرجلُ الذي بين أظهُرِنا قد أعضَلَ -اشتَدَّ أمرُه- بنا، وقد فرَّق جماعَتَنا، وشتَّت أمْرَنا، وإنَّما قَولُه كالسِّحرِ يُفرِّق بين الرَّجلِ وبين أبيه، وبين الرَّجُلِ وبين أخيه، وبين الرَّجُلِ وبين زَوجَتِه، وإنَّا نَخشَى عليك وعلى قَومِك ما قد دَخلَ علينا، فلا تُكلِّمَنَّه ولا تَسمَعَنَّ منه شيئًا\". قال: فَواللهِ ما زالوا بي حتَّى أجمعتُ ألَّا أسمَعَ منه شيئًا ولا أُكلِّمه، حتى حَشَوتُ في أُذُنَيَّ حين غَدَوتُ إلى المسجِدِ كُرسُفًا -قُطنًا- خوفًا مِن أن يَبلُغَني شيءٌ مِن قَولِه، وأنا لا أُريدُ أن أسمَعَه. فغَدَوتُ إلى المسجدِ فإذا رسولُ الله صلَّى اللهُ عليه وسلَّم قائمٌ يصلِّي عند الكَعبةِ. قال: فقُمتُ منه قريبًا، فأبى الله إلَّا أنْ يُسمِعَني بعضَ قولِه. قال: فسَمِعتُ كَلامًا حَسَنًا. فقُلتُ في نَفسي: وا ثُكْلَ أُمِّي، واللهِ إنِّي لرَجلٌ لَبيبٌ شاعِرٌ ما يَخفَى علَيَّ الحَسنُ من القَبيحِ، فما يَمنَعُني أن أسمَعَ من هذا الرَّجلِ ما يقولُ؟ فإنْ كان الذي يَأتي به حَسنًا قَبِلتُه، وإن كان قَبيحًا تَرَكتُه. فمَكَثتُ حتى انصَرَف رسول الله صلَّى اللهُ عليه وسلَّم إلى بيتِه فاتَّبَعتُه، حتى إذا دخل بَيتَه دَخَلتُ عليه، فقلتُ: يا مُحمَّدُ، إنَّ قومَك قد قالوا لي كذا وكذا، للذي قالوا؛ فوالله ما بَرِحوا يُخوِّفونَني أمْرَك حتى سَدَدتُ أُذُنَيَّ بكُرسُفٍ لِئَلَّا أسمَعَ قولَك، ثمَّ أبَى الله إلا أن يُسمِعَني قَولَك، فسَمِعتُه قَولًا حَسَنًا، فاعرِضْ علَيَّ أمْرَك. قال: فعَرَضَ علَيَّ رسولُ الله صلَّى اللهُ عليه وسلَّم الإسلامَ، وتلا علَيَّ القُرآنَ، فلا والله ما سَمعتُ قولًا قطُّ أحسنَ منه، ولا أمرًا أعدَلَ منه. فأسلمتُ وشَهِدتُ شهادةَ الحقِّ، وقلتُ: يا نبيَّ الله، إنِّي امرُؤٌ مُطاعٌ في قومي، وأنا راجِعٌ إليهم، وداعيهِم إلى الإسلامِ، فادعُ الله أن يجعلَ لي آيةً تَكون لي عَونًا عليهم فيما أدعوهم إليه، فقال: \"اللَّهمَّ اجعَل له آيةً\". قال: فخَرَجتُ إلى قومي، حتى إذا كنتُ بثَنيَّةٍ -الفُرجةُ بين الجَبَلَين- تُطلِعُني على الحاضِرِ -أي: القوم النَّازِلين على الماء- وقع نورٌ بين عينَيَّ مِثلُ المِصباحِ، فقُلتُ: اللَّهمَّ في غيرِ وجهي، إنِّي أخشى أن يَظُنُّوا أنَّها مُثلةٌ وَقَعت في وَجهي لفِراقي دينَهم. قال: فتَحَوَّل فوَقَع في رأسِ سوطي. قال: فجَعَل الحاضِرُ يَتراءَون ذلك النُّورَ في سَوطي كالقِنديلِ المُعلَّقِ، وأنا أهبِطُ إليهم من الثَّنيَّةِ، قال: حتى جِئتُهم فأصبَحتُ فيهم. فلمَّا نزلتُ أتاني أبي، وكان شيخًا كبيرًا، قال: فقلتُ: إليك عنِّي يا أبتِ، فلستُ منك ولستَ منِّي. قال: ولِمَ يا بُنَيَّ؟ قال: قلتُ: أسلمتُ وتابَعتُ دينَ محمدٍ صلَّى اللهُ عليه وسلَّم. قال: أيْ بنيَّ، فديني دينُك. قال: فقلتُ: فاذهَبْ فاغتَسِلْ وطهِّرْ ثيابَك، ثم تعالَ حتى أُعَلِّمَك ما عَلِمتُ. فذَهَب فاغتَسَلَ، وطهَّرَ ثيابَه، ثم جاء فعَرَضتُ عليه الإسلامَ، فأسلمَ.ثم أتَتْني صاحِبَتي -زَوجَتي- فقلتُ: إليكِ عنِّي، فلستُ منكِ ولستِ منِّي. قالت: لِمَ؟ بأبي أنت وأمي. قلتُ: قد فرَّق بيني وبينكِ الإسلامُ، وتابَعتُ دينَ محمدٍ صلَّى اللهُ عليه وسلَّم. قالت: فديني دينُكَ. قلتُ: فاذهَبي فتطهَّري، فذَهَبَت فاغتسَلَت، ثم جاءت فعَرَضتُ عليها الإسلامَ، فأسلَمَت. ثم دعوتُ دَوسًا إلى الإسلامِ فأبطَؤوا علَيَّ، ثم جئتُ رسولَ الله صلَّى اللهُ عليه وسلَّم بمكةَ، فقلتُ له: يا نبيَّ الله، إنَّه قد غَلَبني على دوسٍ الزِّنا -لَهوٌ مع شُغُلِ القَلبِ والبَصرِ-، فادعُ الله عليهم، فقال: \"اللَّهمَّ اهدِ دَوسًا، ارجِعْ إلى قومِكَ فادعُهم وارفُقْ بِهِم\". قال: فلَم أزَلْ بأرضِ دَوسٍ أدعوهم إلى الإسلامِ، حتى هاجَرَ رسولُ الله صلَّى اللهُ عليه وسلَّم إلى المدينةِ، ومَضَى بدرٌ وأُحُدٌ والخَندَقُ، ثم قَدِمتُ على رسول الله صلَّى اللهُ عليه وسلَّم بِمَن أسلم معي من قومي، ورسولُ الله صلَّى اللهُ عليه وسلَّم بخَيبَرَ، حتى نزلتُ المدينةَ بسبعين أو ثمانين بَيتًا من دوسٍ، ثم لَحِقْنا برسول الله صلَّى اللهُ عليه وسلَّم بخَيبَرَ، فأسهَمَ لنا مع المسلمين\". ثم لم يَزَل رَضي اللهُ عنه مع رسولِ الله صلَّى اللهُ عليه وسلَّم حتى فتح الله عليه مكَّةَ، وكان معه بالمدينةِ حتى قَبَض الله رسوله صلَّى اللهُ عليه وسلَّم، فلمَّا ارتدَّتِ العربُ خرج مع المسلمين، فسار معهم حتى فَرَغوا من طُلَيحةَ، ومن أرضِ نجدٍ كلِّها. ثم سار مع المسلمين إلى اليَمامةِ، واستشهد فيها."},{"id":22,"title":"حصار قريش للمسلمين في شعب أبي طالب .","date":["العام الهجري :6ق هـ","الشهر القمري : محرم","العام الميلادي :616"],"text":"لمَّا عَزمتْ قُريشٌ أنْ تَقتُلَ رسولَ الله صلى الله عليه وسلم أجمع بَنو عبدِ المُطَّلِبِ أمرَهم على أنْ يُدخِلوا رسولَ الله صلى الله عليه وسلم شِعبَهم ويَحموهُ فيه، فعن أبي هُريرةَ رضي الله عنه، قال: قال النَّبيُّ صلى الله عليه وسلم مِنَ الغَدِ يومَ النَّحْرِ، وهو بمِنًى: «نحن نازِلون غدًا بِخَيْفِ بني كِنانةَ؛ حيث تقاسموا على الكُفرِ» يعني ذلك المُحَصَّبَ، وذلك أنَّ قُريشًا وكِنانةَ، تحالفتْ على بني هاشمٍ وبني عبدِ المُطَّلبِ، أو بني المُطَّلبِ: أنْ لا يُناكِحوهُم ولا يُبايِعوهُم، حتَّى يُسلِموا إليهِمُ النَّبيَّ صلى الله عليه وسلم، فدخلوا الشِّعْبَ جميعًا مُسلِمهُم وكافِرهُم، وأجمعَ المشركون أمرَهُم على أنْ لا يُجالِسوهُم، ولا يُخالِطوهُم، ولا يُبايِعوهُم، ولا يَدخُلوا بُيوتَهم، حتَّى يُسلِموا رسولَ الله للقتلِ، وكتبوا في ذلك صَحيفةً، فلبِث بنو هاشمٍ في شِعبهِم ثلاثَ سِنينَ، واشتدَّ عليهِم البلاءُ والجهدُ والجوعُ، فلمَّا كان رأس ثلاثِ سِنينَ تَلاوَمَ رجالٌ من قُريشٍ على ما حدث وأجمعوا على نَقضِ الصَّحيفةِ، وهكذا انتهتْ المقاطعةُ."},{"id":23,"title":"نَقْضُ قريش لمِيثاقِ الصَّحيفةِ .","date":["العام الهجري :3ق هـ","الشهر القمري : محرم","العام الميلادي :619"],"text":"بعدَ مُرورِ عامينِ أو ثلاثةِ أَعوامٍ مِنَ الحِصارِ الظَّالمِ في شِعْبِ أبي طالبٍ نُقِضتْ الصَّحيفةُ وفُكَّ الحِصارُ؛ وذلك أنَّ قُريشًا كانوا بين راضٍ بهذا الميثاقِ وكارهٍ له، فسعى في نَقْضِ الصَّحيفةِ مَنْ كان كارهًا لها, وكان القائمُ بذلك هشامُ بنُ عَمرٍو مِن بني عامرِ بنِ لُؤَيٍّ, وكان يَصِلُ بني هاشمٍ في الشِّعْبِ مُستَخفِيًا باللَّيلِ بالطَّعامِ, فإنَّه ذهب إلى زُهيرِ بنِ أبي أُمَيَّةَ المخزوميِّ -وكانت أمُّه عاتِكَةَ بنتَ عبدِ المُطَّلبِ- وقال: يا زُهيرُ، أَرَضيتَ أنْ تَأكُلَ الطَّعامَ، وتَشربَ الشَّرابَ، وأَخوالُكَ بحيث تعلمُ؟ فقال: ويحكَ، فما أصنعُ وأنا رجلٌ واحدٌ؟ أما والله لو كان معي رجلٌ آخرُ لقمتُ في نَقضِها. قال: قد وجدتَ رجلًا. قال: فمن هو؟ قال: أنا. قال له زُهيرٌ: ابْغِنا رجلًا ثالثًا. فذهب إلى المُطْعِمِ بنِ عَدِيٍّ، فذكَّرهُ أَرحامَ بني هاشمٍ وبني المُطَّلبِ ابنيْ عبدِ مَنافٍ، ولَامَهُ على مُوافقتِهِ لِقُريشٍ على هذا الظُّلمِ، فقال المُطْعِمُ: ويحكَ، ماذا أصنعُ؟ إنَّما أنا رجلٌ واحدٌ. قال: قد وجدتَ ثانيًا. قال: من هو؟ قال: أنا. قال: ابغِنا ثالثًا. قال: قد فعلتُ. قال: من هو؟ قال: زُهيرُ بنُ أبي أُمَيَّةَ. قال: ابغِنا رابعًا. فذهب إلى أبي البَخْتريِّ بنِ هشامٍ، فقال له نحوًا ممَّا قال للمُطْعِمِ، فقال: وهل مِن أحدٍ يُعينُ على هذا؟ قال: نعم. قال: مَن هو؟ قال زُهيرُ بنُ أبي أُمَيَّةَ، والمُطْعِمُ بنُ عَدِيٍّ، وأنا معك. قال: ابغِنا خامسًا. فذهب إلى زَمعةَ بنِ الأسودِ بنِ المُطَّلبِ بنِ أسدٍ، فكلَّمهُ, وذكر له قرابتَهُم وحقَّهُم، فقال له: وهل على هذا الأمرِ الذي تُدعوني إليه مِن أحدٍ؟ قال: نعم. ثم سَمَّى له القومَ، فاجتمعوا عند الحَجُونِ، وتعاقدوا على القيامِ بنَقضِ الصَّحيفةِ، وقال زُهيرٌ: أنا أَبدأُكم فأكونُ أوَّلَ مَن يتكلَّمُ. فلمَّا أصبحوا غَدَوْا إلى أَنْدِيَتِهِم، وغدا زُهيرٌ عليه حُلَّةٌ، فطاف بالبيتِ سبعًا، ثمَّ أقبل على النَّاسِ، فقال: يا أهلَ مكَّة، أنأكلُ الطَّعامَ, ونَلبَسُ الثِّيابَ, وبنو هاشمٍ هَلْكى، لا يُباع ولا يُبتاعُ منهم؟ والله لا أقعدُ حتَّى تُشَقَّ هذه الصَّحيفةُ القاطعةُ الظَّالمةُ. قال أبو جهلٍ, وكان في ناحيةِ المسجدِ: كذبتَ، والله لا تُشَقُّ. فقال زَمعةُ بنُ الأسودِ: أنت والله أَكْذَبُ، ما رضينا كتابتَها حيث كُتِبتْ. قال أبو البَخْتريِّ: صدق زَمعةُ، لا نرضى ما كُتِبَ فيها، ولا نُقِرُّ به. قال المُطْعِمُ بنُ عَدِيٍّ: صدقتُما، وكذب مَن قال غيرَ ذلك، نبرأُ إلى الله منها وممَّا كُتِبَ فيها. وقال هشامُ بنُ عَمرٍو نحوًا من ذلك. فقال أبو جهلٍ: هذا أمر قُضِيَ بليلٍ، وتُشُووِر فيه بغيرِ هذا المكانِ. وأبو طالبٍ جالسٌ في ناحيةِ المسجدِ، إنمَّا جاءهُم لأنَّ الله كان قد أَطلعَ رسولَه صلى الله عليه وسلم على أمرِ الصَّحيفةِ، وأنَّه أرسلَ عليها الأَرَضَةَ، فأكلتْ جميعَ ما فيها من جَورٍ وقَطيعةٍ وظُلمٍ إلا ذكرَ الله عزَّ وجلَّ، فأَخبر بذلك عمَّه، فخرج إلى قُريشٍ فأخبرهم أنَّ ابنَ أخيهِ قد قال كذا وكذا، فإنْ كان كاذبًا خَلَّيْنا بينكم وبينه، وإنْ كان صادقًا رجعتُم عن قطيعتِنا وظُلمِنا. قالوا: قد أنصفتَ. وبعد أنْ دار الكلامُ بين القومِ وبين أبي جهلٍ، قام المُطعمِ إلى الصَّحيفةِ لِيَشُقَّها، فوجد الأَرَضَةَ قد أكلتْها إلَّا (باسمِك اللَّهمَّ)، وما كان فيها مِن اسمِ الله فإنَّها لم تأكلْهُ. ثم نقضَ الصَّحيفةَ وخرج رسولُ الله صلى الله عليه وسلم ومَن معه مِنَ الشِّعبِ، وقد رأى المشركون آيةً عظيمةً مِن آياتِ نُبوَّتِه، ولكنَّهم  كما أخبر الله عنهم: (وَإِن يَرَوْا آيَةً يُعْرِضُوا وَيَقُولُوا سِحْرٌ مُّسْتَمِرٌّ ) أعرضوا عن هذه الآيةِ وازدادوا كُفرًا إلى كُفرهِم."},{"id":24,"title":"وَفاةُ أمِّ المؤمنين خَديجةَ بنتِ خويلدٍ رضِي الله عنها .","date":["العام الهجري :3ق هـ","الشهر القمري : رمضان","العام الميلادي :620"],"text":"هي خَديجةُ بنتُ خويلدِ بنِ أسدِ بنِ عبدِ العُزَّى بنِ قُصَيِّ بنِ كِلابٍ، مِن خيرِ نِساءِ الدُّنيا، أتى جبريلُ النَّبيَّ صلى الله عليه وسلم فقال: يا رسولَ الله، هذه خديجةُ قد أتتْكَ بإناءٍ فيه إدامٌ -أو طعامٌ أو شرابٌ- فإذا أتتْكَ فَاقرأْ عليها السَّلامَ مِن رَبِّها ومِنِّي، وبَشِّرها بِبيتٍ في الجنَّةِ من قَصبٍ لا صَخَبَ فيهِ ولا نَصَبَ. كانتْ خَديجةُ أوَّلَ مَنْ أَسلمَ بالنَّبيِّ صلى الله عليه وسلم. آمنتْ بهِ إذ كفرَ بهِ النَّاسُ، وآوَتْهُ إذ رَفضهُ النَّاسُ، وصَدَّقتهُ إذ كَذَّبهُ النَّاسُ، ورزقهُ الله منها الوَلَدَ: القاسِمَ، والطَّيِّبَ، والطَّاهِرَ، ماتوا رضعًا، ورُقيَّةَ، وزَينبَ، وأمَّ كَلثومٍ، وفاطمةَ, توفِّيتْ رضي الله عنها وأبو طالبٍ في عامٍ واحدٍ، فتتابعتْ على رسولِ الله صلى الله عليه وسلم المصائبُ بموتهِما, فكانتْ خَديجةُ وَزيرةَ صِدقٍ على الإسلامِ، وكان النَّبيُّ صلى الله عليه وسلم يَسكُن إليها. «توفِّيتْ خَديجةُ قبلَ مَخرجِ النَّبيِّ صلى الله عليه وسلم إلى المدينةِ بثلاثِ سِنينَ، فلَبِثَ سَنتينِ أو قريبًا من ذلك، ونكحَ عائشةَ وهي بنتُ سِتِّ سِنينَ، ثمَّ بنى بها وهي بنتُ تِسعِ سِنينَ» توفِّيتْ أمُّ المؤمنين خَديجةُ بنتِ خويلدٍ رضِي الله عنها في مكَّة، ودُفِنتْ بالحَجونِ."},{"id":25,"title":"خُروجُ رسولِ الله صلَّى الله عَليهِ وسلَّم إلى الطَّائفِ .","date":["العام الهجري :3ق هـ","الشهر القمري : شوال","العام الميلادي :620"],"text":"خرج النَّبيُّ صلى الله عليه وسلم إلى الطَّائفِ، وهي تَبعُد عن مكَّة نحوَ سِتِّينَ مِيلًا، سارها ماشِيًا على قَدميهِ جِيئةً وذِهابًا، ومعه مولاهُ زيدُ بنُ حارثةَ، وكان كُلَّما مَرَّ على قَبيلةٍ في الطَّريقِ دعاهُم إلى الإسلامِ، فلمْ تُجبْ إليهِ واحدةٌ منها, فلمَّا انتهى إلى الطَّائفِ عَمَدَ إلى رُؤسائِها فدعاهُم فلمْ يَستجيبوا له, فأقام بين أهلِ الطَّائفِ عشرةَ أيَّامٍ، لا يَدَعُ أحدًا مِنْ أشرافهِم إلا جاءهُ وكَلَّمهُ، فقالوا: اخرُجْ من بلادِنا. وأَغْرَوْا به سُفهاءَهُم، فلمَّا أراد الخُروجَ تَبِعَهُ سُفهاؤهُم وعَبيدهُم يُسِبُّونَهُ ويُصيحونَ بهِ، حتَّى اجتمع عَليهِ النَّاسُ، فوقَفوا له سِمَاطَيْنِ [أي صَفَّيْنِ] وجعلوا يَرمونهُ بالحِجارةِ، وبكِلماتٍ مِنَ السَّفَهِ، ورَجموا عَراقيبَهُ، حتَّى اخْتَضَبَ نَعلاهُ بالدِّماءِ. وكان زيدُ بنُ حارثةَ يَقِيهِ بِنفسهِ حتَّى أصابهُ شِجَاجٌ في رَأسهِ، ولم يزلْ بهِ السُّفهاءُ كذلك حتَّى أَلجأوهُ إلى حائطٍ لعُتبةَ وشَيبةَ ابنيْ رَبيعةَ على ثلاثةِ أميالٍ مِنَ الطَّائفِ, ورجع رسولُ الله صلى الله عليه وسلم في طريقِ مكَّة بعدَ خُروجهِ مِنَ الحائطِ كَئيبًا مَحزونًا، كَسيرَ القلبِ، فلمَّا بلغ قَرْنَ المنازلِ بعث الله إليه جبريلَ ومعه مَلَكُ الجبالِ، يَسْتَأْمِرُهُ أنْ يُطْبِقَ الأَخْشَبَيْنِ على أهلِ مكَّة, فقال النَّبيُّ صلى الله عليه وسلم: (بل أرجو أنْ يُخرجَ الله عزَّ وجلَّ من أصلابهِم مَنْ يَعبدُ الله عزَّ وجلَّ وحدَه لا يُشركُ بهِ شيئًا). وفي هذا الجوابِ الذي أَدلى بهِ الرَّسولُ صلى الله عليه وسلم تَتجلَّى شَخصيَّتُه الفَذَّةُ، وما كان عَليهِ من خُلُقٍ عَظيمٍ."},{"id":26,"title":"إِسلامُ الجِنِّ وتَوافُدهُم على النَّبيِّ صلَّى الله عَليهِ وسلَّم  .","date":["العام الهجري :3ق هـ","الشهر القمري : شوال","العام الميلادي :620"],"text":"لمَّا انصرف النَّبيُّ صلى الله عليه وسلم مِنَ الطَّائفِ راجعًا إلى مكَّة، حتَّى إذا كان بِنَخْلَةَ، قام من جوفِ اللَّيلِ يُصلِّي، فمَرَّ بهِ النَّفرُ مِنَ الجِنِّ الذين ذكَرهُم الله تعالى، وكانوا سَبعةَ نَفَرٍ من جِنِّ أهلِ نَصِيبِينَ، فاستمعوا لِتِلاوةِ الرَّسولِ صلى الله عليه وسلم، فلمَّا فرغ من صلاتهِ، وَلَّوْا إلى قَومهِم مُنذِرين، قد آمنوا وأجابوا إلى ما سمِعوا، وفيهِم نزل قولُه تعالى: (وَإِذْ صَرَفْنَا إِلَيْكَ نَفَرًا مِّنَ الْجِنِّ يَسْتَمِعُونَ الْقُرْآنَ فَلَمَّا حَضَرُوهُ قَالُوا أَنصِتُوا فَلَمَّا قُضِيَ وَلَّوْا إِلَىٰ قَوْمِهِم مُّنذِرِينَ (29) قَالُوا يَا قَوْمَنَا إِنَّا سَمِعْنَا كِتَابًا أُنزِلَ مِن بَعْدِ مُوسَىٰ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ يَهْدِي إِلَى الْحَقِّ وَإِلَىٰ طَرِيقٍ مُّسْتَقِيمٍ (30) يَا قَوْمَنَا أَجِيبُوا دَاعِيَ اللَّهِ وَآمِنُوا بِهِ يَغْفِرْ لَكُم مِّن ذُنُوبِكُمْ وَيُجِرْكُم مِّنْ عَذَابٍ أَلِيمٍ(31) وَمَن لَّا يُجِبْ دَاعِيَ اللَّهِ فَلَيْسَ بِمُعْجِزٍ فِي الْأَرْضِ وَلَيْسَ لَهُ مِن دُونِهِ أَوْلِيَاءُ أُولَٰئِكَ فِي ضَلَالٍ مُّبِينٍ (32)) [الأحقاف]  وبعدَ عِدَّةِ أَشهُرٍ من لِقاءِ الوفدِ الأوَّلِ مِنَ الجِنِّ بِرسولِ الله صلى الله عليه وسلم, جاء الوفدُ الثَّاني مُتشوِّقاً لِرُؤيةِ الحبيبِ المصطفى صلى الله عليه وسلم, والاستماعِ إلى كلامِ رَبِّ العالمين."},{"id":27,"title":"وَفاةُ أبي طالبٍ عَمِّ النَّبيِّ صلَّى الله عَليهِ وسلَّم .","date":["العام الهجري :3ق هـ","الشهر القمري : شوال","العام الميلادي :620"],"text":"بعدَ أنِ اشْتدَّ المرضُ على أبي طالبٍ عَمِّ النَّبيِّ صلى الله عليه وسلم وهو الذي كفله صغيرًا، وآزرَهُ كبيرًا، وناصرَهُ على دَعوتهِ، وحَماهُ من عَوادي المشركين، دخل عَليهِ النَّبيُّ صلى الله عليه وسلم وعندهُ أبو جَهْلٍ، فقال: ( أي عَمِّ، قُلْ: لا إلَه إلَّا الله، كلمةً أُحاجُّ لك بها عندَ الله). فقال أبو جَهْلٍ وعبدُ الله بنُ أبي أُمَيَّةَ: يا أبا طالبٍ، تَرغبُ عن مِلَّةِ عبدِ المُطَّلبِ؟ فلم يَزالا يُكلِّماهُ حتَّى قال آخرَ شيءٍ كَلَّمهُم بهِ: على مِلَّةِ عبدِ المُطَّلبِ. فقال النَّبيُّ صلى الله عليه وسلم: (لأَستَغفِرَنَّ لك ما لمْ أُنْهَ عنهُ). فنزلتْ: {مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُواْ أَن يَسْتَغْفِرُواْ لِلْمُشْرِكِينَ وَلَوْ كَانُواْ أُوْلِي قُرْبَى مِن بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَابُ الْجَحِيمِ}ونزلتْ: {إِنَّكَ لَا تَهْدِي مَنْ أَحْبَبْتَ}. وقد كان أبو طالبٍ الحِصْنَ الذي احتَمى بهِ النَّبيُّ صلى الله عليه وسلم من هَجماتِ الكُبراءِ والسُّفهاءِ، ولكنَّه بَقِيَ على مِلَّةِ الأَشياخِ من أَجدادهِ، فلمْ يُفلِحْ."},{"id":28,"title":"زَواجُ النَّبيِّ صلَّى الله عَليهِ وسلَّم من سَوْدَةَ بنتِ زَمْعَةَ رضِي الله عنها .","date":["العام الهجري :3ق هـ","الشهر القمري : شوال","العام الميلادي :620"],"text":"بعدَ وفاةِ أمِّ المؤمنين خَديجةَ بنتِ خويلدٍ رضي الله عنها والتي كانت مِن نِعَمِ الله الجَليلةِ على رسولِ الله صلى الله عليه وسلم، تَزوَّج رسولُ الله صلى الله عليه وسلم سَودةَ بنتَ زَمْعَةَ بنِ قَيسِ بنِ عبدِ شمسِ بنِ عبدِ وُدِّ بنِ نصرِ بنِ مالكِ بن حِسْلِ بنِ عامرِ بن لُؤَيٍّ، القُرشيَّةَ، تَزوَّجها بمكَّة قبلَ الهِجرةِ، وكانت ممَّن أسلمَ قديمًا, وهاجرتْ الهِجرةَ الثَّانيةَ إلى الحَبشةِ، وكان زوجُها السَّكرانَ بنَ عَمرٍو، وكان قد أَسلمَ وهاجر معها، فمات بأرضِ الحَبشةِ، أو بعدَ الرُّجوعِ إلى مكَّة، فلمَّا حَلَّتْ خطبَها رسولُ الله صلى الله عليه وسلم وتَزوَّجها، وكانتْ أوَّلَ امرأةٍ تَزوَّجها بعدَ وفاةِ خَديجةَ، وكانتْ في العَقْدِ السَّادسِ من عُمُرِها وقتَها، ولمَّا أراد النَّبيُّ صلى الله عليه وسلم طلاقَها صالَحَتْهُ بأنْ وَهبتْ نَوْبَتَها لِعائشةَ رضي الله عنها فأَمْسَكها، ولمْ يُصِبْ منها ولدًا حتَّى مات صلى الله عليه وسلم."},{"id":29,"title":"بداية دخول الأنصار في الإسلام .","date":["العام الهجري :3ق هـ","الشهر القمري : ذي الحجة","العام الميلادي :620"],"text":"لمَّا أراد الله عزَّ وجلَّ إظهارَ دينهِ، وإعزازَ نَبيِّهِ صلى الله عليه وسلم، وإنجازَ مَوعِدِه له خرج رسولُ الله صلى الله عليه وسلم في مَوسمِ الحجِّ يَعرِضُ نَفْسَهُ على قبائلِ العربِ، كما كان صنع في كُلِّ مَوسمٍ. فبينما هو عند العَقبةِ لَقِيَ رهطًا مِنَ الخَزرجِ أراد الله بهم خيرًا فقال لهم مَن أنتم؟ قالوا: نَفرٌ مِنَ الخَزرجِ، قال أمِن موالي يَهودَ؟ قالوا: نعم. قال أفلا تَجلِسون أُكلِّمكُم؟ قالوا: بلى. فجلسوا معه فدعاهم إلى الله عزَّ وجلَّ، وعرض عليهم الإسلامَ، وتلا عليهم القُرآنَ. وكان مما صنع الله لهم به في الإسلامِ أنَّ يَهودَ كانوا معهم في بلادِهم، وكانوا يتَوعَّدونَهُم بِقُربِ ظُهورِ نَبِيٍّ يتَّبِعونهُ ثمَّ يَقتلون معه العربَ قتلَ إِرَمَ, فلمَّا كلَّمهُم صلَّى الله عليه وسلَّم ودعاهم إلى الله قال بعضُهم لبعضٍ: يا قومُ، تعلموا والله إنَّه للنَّبيُّ الذي تَوعَّدكُم به يَهودُ فلا تَسْبِقَنَّكُم إليه. فأجابوه فيما دعاهم إليه وقالوا له: إنَّا قد تركنا قومَنا، ولا قومٌ بينهم مِنَ العَداوةِ والشَّرِّ ما بينهم، وعسى أن يجمعَهُم الله بكَ. فَسنَقدَمُ فنَدعوهُم إلى أمرِك، ونعرِضُ عليهم الذي أجبناك إليه من هذا الدِّينِ، فإن يَجمعْهُم الله عليك فلا رجلَ أعزُّ منك. ثمَّ انصرفوا راجِعين إلى بلادِهم، قد آمنوا وصدَّقوا\". فلمَّا قَدِموا المدينةَ إلى قومِهم ذكروا لهم رسولَ الله صلى الله عليه وسلم، ودَعوهُم إلى الإسلامِ حتَّى فَشا فيهِم فلمْ يَبْقَ دارٌ مِن دورِ الأنصارِ إلَّا وفيها ذِكْرٌ مِن رسولِ الله صلى الله عليه وسلم."},{"id":30,"title":"زَواجُ النَّبيِّ مِن عائشةَ بنتِ أبي بكرٍ الصِّدِّيقِ رضِي الله عنهُما .","date":["العام الهجري :2ق هـ","الشهر القمري : محرم","العام الميلادي :620"],"text":"تَزوَّج رسولُ الله صلى الله عليه وسلم عائشةَ الصِّدِّيقةَ رضي الله عنها وهي بنتُ سِتِّ سِنينَ, وبَنى بها بالمدينةِ في شَوَّال في السَّنةِ الثانية مِن الهِجرةِ وهي بنتُ تِسعِ سِنينَ, وكانت أَحظى أزواجِه عنده وأحبَّهُم إليه, ولمْ يتزوَّجْ بِكرًا غيرَها."},{"id":31,"title":"بَيْعةُ العَقبةِ الأولى  .","date":["العام الهجري :2ق هـ","الشهر القمري : ذي الحجة","العام الميلادي :621"],"text":"عن عُبادةَ بنِ الصَّامتِ رضي الله عنه أحدُ النُّقَباءِ ليلةَ العَقبةِ: أنَّ رسولَ الله صلَّى الله عليه وعلى آله وصَحبِه وسلَّم قال وحولَه عِصابةٌ مِن أصحابهِ: (بايِعوني على أنْ لا تُشرِكوا بالله شيئًا، ولا تَسرِقوا، ولا تَزنوا، ولا تَقتُلوا أولادَكُم، ولا تَأتوا ببُهْتانٍ تَفتَرونهُ بين أيديكُم وأرجُلِكُم، ولا تَعْصوا في مَعروفٍ، فمَن وَفَّى منكم فأجرُهُ على الله، ومَن أصاب مِن ذلك شيئًا فعُوقِبَ في الدُّنيا فهو كفَّارةٌ له، ومَن أصاب مِن ذلك شيئًا ثمَّ سَترهُ الله فهو إلى الله، إن شاء عَفا عنه، وإن شاء عاقَبهُ). قال: فبايَعناهُ على ذلك."},{"id":32,"title":"الإسراءُ والمِعراجُ وفرضُ الصَّلواتِ الخمسِ .","date":["العام الهجري :1ق هـ","العام الميلادي :621"],"text":"في هذه الحادثةِ العظيمةِ رأى النَّبيُّ صلى الله عليه وسلم الأنبياءَ، ورأى سِدرةَ المُنتهى وغيرَ ذلك مِنَ الآياتِ العظيمةِ، وفيها فُرِضتْ الصَّلواتُ الخمسُ، وهو أمرٌ تتَّفِقُ عليه رِواياتُ الصَّحيحينِ، وقد كذَّبتْ قُريشٌ وقوعَ حادثةِ الإسراءِ والمِعراجِ، وهذا أمرٌ اتَّفقتْ عليه رِواياتُ الصَّحيحينِ أيضًا، قال رسولُ الله صلى الله عليه وسلم:\"لقد رأيتُني في الحِجْرِ وقُريشٌ تسألُني عن مَسْرايَ، فسألَتني عن أشياءَ مِن بيتِ المَقدسِ لم أُثْبِتْها، فكُرِبْتُ كُربةً ما كُرِبْتُ مِثلَهُ قَطُّ». قال: \" فرفعهُ الله لي أنظرُ إليه، ما يسألوني عن شيءٍ إلَّا أنبأتُهم به، وقد رأيتُني في جماعةٍ مِنَ الأنبياءِ، فإذا موسى قائمٌ يُصلِّي، فإذا رجلٌ ضَرْبٌ، جَعْدٌ كأنَّه مِن رجالِ شَنُوءَةَ، وإذا عيسى ابنُ مريمَ عليه السَّلامُ قائمٌ يُصلِّي، أقربُ النَّاسِ به شَبَهًا عُروةُ بنُ مَسعودٍ الثَّقفيُّ، وإذا إبراهيمُ عليه السَّلامُ قائمٌ يُصلِّي، أَشْبَهُ النَّاسِ به صاحبُكم - يعني نَفْسَهُ - فحانتِ الصَّلاةُ فأَمَمْتُهُم، فلمَّا فَرَغْتُ مِنَ الصَّلاةِ قال قائلٌ: يا محمَّدُ، هذا مالكٌ صاحبُ النَّارِ، فَسلِّمْ عليه، فالتفَتُّ إليه، فبدأَني بالسَّلامِ \"."},{"id":33,"title":"هِجرةُ أبي سَلمةَ وأمِّ سَلمةَ رضي الله عنهما .","date":["العام الهجري :1ق هـ","الشهر القمري : محرم","العام الميلادي :621"],"text":"كان أبو سَلمةَ عبدُ الله بنُ عبدِ الأسدِ أوَّلَ مَن هاجر إلى المدينةِ مِن أصحابِ رسولِ الله صلى الله عليه وسلم مِنَ المُهاجرين مِن قُريشٍ مِن بني مَخزومٍ، وكانتْ هِجرتُه إليها بعدَ بَيعةِ العَقبةِ الأولى، وقبلَ بَيعةِ العَقبةِ الثَّانيةِ، حين آذتْهُ قُريشٌ بعدَ مَرجعِهِ مِنَ الحَبشةِ، فعزم على الرُّجوعِ إليها، ثمَّ بَلغهُ أنَّ بالمدينةِ لهم إخوانًا، فعزم في الهِجرةِ إليها.قالتْ أمُّ سَلمةَ: لمَّا أجمع أبو سَلمةَ الخُروجُ إلى المدينةِ رَحَّلَ لي بَعيرَهُ ثمَّ حملَني عليه، وجعل معي ابْنِي سَلمةَ بنَ أبي سَلمةَ في حِجْري، ثمَّ خرج يقود بي بَعيرَهُ، وانطلق به بنو عبدِ الأسدِ، وحبسني بنو المُغيرةِ عندهم وانطلق زوجي أبو سَلمةَ إلى المدينةِ. قالتْ: ففُرِّق بيني وبين ابْنِي وبين زوجي. قالت: فكنتُ أخرُج كُلَّ غَداةٍ فأجلِسُ في الأَبْطَحِ، فما أزالُ أبكي حتَّى أُمْسي، سَنَةً أو قريبًا منها، حتَّى مَرَّ بي رجلٌ مِن بني عَمِّي أحدُ بني المُغيرةِ، فرأى ما بي فرحِمَني، فقال لِبَني المُغيرةِ: ألا تحرجون من هذه المِسكينةِ؟ فرَّقتُم بينها وبين زوجِها وبين ولدِها؟ قالت: فقالوا لي: الْحَقي بزوجِك إن شئتِ. قالت: فَرَدَّ بنو عبدِ الأسدِ إليَّ عند ذلك ابْنِي، قالت: فارتحلتُ بعيري، ثمَّ أخذتُ ابْنِي فوضعتُه في حِجْري، ثمَّ خرجتُ أُريدُ زوجي بالمدينةِ. قالت: وما معي أحدٌ من خَلقِ الله، حتَّى إذا كنتُ بالتَّنعيمِ لَقيتُ عُثمانَ بنَ طلحةَ بنِ أبي طلحةَ أخا بني عبدِ الدَّارِ، فقال: إلى أين يا ابنةَ أبي أُميَّةَ؟ قلتُ: أُريدُ زوجي بالمدينةِ. قال: أَوَمَا معكِ أحدٌ؟ قلتُ: ما معي أحدٌ إلَّا الله وابْنِي هذا. فقال: والله ما لكِ مِن مَتْرَكٍ. فأخذ بخِطامِ البَعيرِ فانطلق معي يَهْوي بي، فَوَالله ما صَحِبتُ رجلًا مِن العربِ قَطُّ أَرى أنَّه كان أَكرمَ منه، كان إذا بلغ المنزِلَ أناخ بي، ثمَّ استأخر عنِّي حتَّى إذا نزلتُ استأخر ببعيري فحَطَّ عنه ثمَّ قيَّدهُ في الشَّجرِ، ثمَّ تنحَّى إلى شجرةٍ فاضطجع تحتها. فإذا دَنا الرَّواحُ قام إلى بعيري فقدَّمهُ فَرَحَّلَهُ، ثمَّ استأخر عنِّي وقال: ارْكَبي. فإذا رَكِبْتُ فاستويتُ على بعيري أتى فأخذ بخِطامهِ فقادَني حتَّى يَنزِلُ بي، فلمْ يَزلْ يصنعُ ذلك بي حتَّى أَقْدَمَني المدينةَ، فلمَّا نظر إلى قريةِ بني عَمرِو بنِ عَوفٍ بقُباءٍ قال: زوجُكِ في هذه القريةِ. وكان أبو سَلمةَ بها نازلًا، فادْخُليها على بركةِ الله. ثمَّ انصرف راجعًا إلى مكَّةَ. فكانت تقولُ أمُّ سَلمةَ: ما أعلمُ أهلَ بيتٍ في الإسلامِ أصابهم ما أصاب آلَ أبي سَلمةَ، وما رأيتُ صاحبًا قَطُّ كان أكرمَ مِن عُثمانَ بنِ طلحةَ. أَسلمَ عُثمانُ بنُ طلحةَ بنِ أبي طلحةَ العَبْدَريُّ بعدَ الحُدَيبيةِ."},{"id":34,"title":"انتِشارُ الإسلامِ في يَثْرِبَ بعدَ العَقبةِ الأولى .","date":["العام الهجري :1ق هـ","الشهر القمري : محرم","العام الميلادي :621"],"text":"كتب الأنصارُ إلى رسولِ الله صلى الله عليه وسلم بعدَ بَيعةِ العَقبةِ الأولى أن يبعثَ لهم مَن يُصلِّي بهم ويُقريهِم القُرآنَ، فبعث رسولُ الله صلى الله عليه وسلم لهم مُصعبَ بنَ عُميرٍ, فكان في ضِيافةِ أَسعدَ بنِ زُرارةَ, وأخذ يدعو إلى الإسلامِ، وانتشر الإسلامُ في أهلِ يَثْرِبَ حتَّى لمْ يَبْقَ بيتٌ في يَثْرِبَ إلَّا وفيه مُسلمٌ أو مُسلمةٌ، وكان ممَّن أَسلمَ على يدِهِ سَيِّدا الأَوسِ سعدُ بنُ مُعاذٍ، وأُسيدُ بنُ الحُضيرِ."},{"id":35,"title":"بَيعةُ العَقبةِ الثَّانيةِ .","date":["العام الهجري :1ق هـ","الشهر القمري : ذي الحجة","العام الميلادي :622"],"text":"عن جابرٍ قال: (مكث رسولُ الله صلى الله عليه وسلم بمكَّةَ عشرَ سِنينَ يَتْبَعُ النَّاسَ في منازلِهم بعُكاظٍ ومَجَنَّةَ، وفي المَواسمِ بمِنًى، يقول: مَن يُؤْوِيني؟ مَن يَنصُرني حتَّى أُبَلِّغَ رسالةَ رَبِّي وله الجَنَّةُ. حتَّى إنَّ الرَّجلَ لَيخرُجُ مِنَ اليمنِ أو مِن مُضَرَ، فيأتيه قومُه فيقولون: احْذرْ غُلامَ قُريشٍ لا يَفْتِنُكَ. ويمشي بين رجالِهم وهُم يُشيرون إليه بالأصابعِ حتَّى بعثنا الله إليه مِن يَثْرِبَ فآوَيناهُ وصدَّقناهُ، فيخرُج الرَّجلُ مِنَّا فيُؤمِنُ به ويُقرِئُهُ القُرآنَ فيَنقلِبُ إلى أهلهِ فيُسلِمون بإسلامهِ، حتَّى لمْ يَبْقَ دارٌ مِن دورِ الأنصارِ إلَّا وفيها رَهطٌ مِنَ المسلمين يُظهِرون الإسلامَ، ثمَّ ائْتَمروا جميعًا فقُلنا: حتَّى متى نَترُك رسولَ الله صلَّى الله عليه وسلَّم يُطْرَدُ في جبالِ مكَّةَ ويخافُ. فرحل إليه مِنَّا سبعون رجلًا حتَّى قَدِموا عليه في المَوسمِ فَواعَدناهُ شِعْبَ العَقبةِ، فاجتمَعنا عليه مِن رجلٍ ورَجُلَينِ حتَّى تَوافَينا فقُلنا: يا رسولَ الله، نُبايِعُك. قال: تُبايِعوني على السَّمعِ والطَّاعةِ في النَّشاطِ والكَسلِ، والنَّفقةِ في العُسرِ واليُسرِ، وعلى الأمرِ بالمعروفِ والنَّهيِ عن المُنكرِ، وأن تقولوا في الله لا تخافون في الله لَوْمَةَ لائمٍ، وعلى أن تَنصُروني فتَمنَعوني إذا قَدِمتُ عليكم ممَّا تمنَعون منه أنفسَكُم وأَزواجَكُم وأبناءَكُم ولكم الجنَّةُ. قال فقُمنا إليه فبايَعناهُ، وأخذ بيدِهِ أَسعدُ بنُ زُرارةَ وهو مِن أَصغرِهم، فقال: رُويدًا يا أهلَ يَثْرِبَ، فإنَّا لمْ نَضرِبْ أَكبادَ الإبلِ إلَّا ونحن نعلمُ أنَّه رسولُ الله صلَّى الله عليه وسلَّم، وإنَّ إخراجَهُ اليومَ مُفارقةُ العربِ كافَّةً، وقَتْلُ خِيارِكُم، وأنْ تَعَضَّكُم السُّيوفُ، فإمَّا أنتم قومٌ تَصبِرون على ذلك وأَجرُكم على الله، وإمَّا أنتم قومٌ تخافون مِن أَنفُسِكُم جَبِينَةً فَبَيِّنوا ذلك فهو عُذْرٌ لكم عند الله. قالوا أَمِطْ عنَّا يا أَسعدُ، فَوَالله لا نَدَعُ هذه البَيعةَ أبدًا، ولا نَسْلُبُها أبدًا. قال فقُمنا إليه فبايَعناهُ فأخذ علينا وشَرَطَ ويُعطينا على ذلك الجنَّةَ)"},{"id":36,"title":"مُعجِزةُ انشِقاقِ القَمرِ .","date":["العام الهجري :0","العام الميلادي :622"],"text":"عن عبدِ الله بنِ مَسعودٍ رضي الله عنه، قال: انشقَّ القَمرُ على عهدِ رسولِ الله صلى الله عليه وسلم شِقَّتينِ، فقال النَّبيُّ صلى الله عليه وسلم: «اشْهَدوا». وعن أنسِ بنِ مالكٍ رضي الله عنه، «أنَّ أهلَ مكَّة سألوا رسولَ الله صلى الله عليه وسلم أنْ يُرِيَهُم آيةً، فأراهُم القَمرَ شِقَّتينِ، حتَّى رَأَوْا حِراءً بينهُما» وفي صحيحِ مُسلمٍ عن عبدِ الله بنِ مَسعودٍ قال: انشقَّ القَمرُ على عهدِ رسولِ الله صلَّى الله عَليهِ وسلَّم فِلقَتَينِ، فسَترَ الجبلُ فِلْقَةً، وكانتْ فِلْقَةٌ فوقَ الجبلِ، فقال رسولُ الله صلى الله عليه وسلم: «اللَّهُمَّ اشْهدْ». والمشهورُ أنَّ انشِقاقَ القَمرِ حصلَ مَرَّةً واحدةً، أمَّا ما وردَ في إِحدى رِواياتِ مُسلمٍ: (.. فأَراهُم انشِقاقَ القَمرِ مَرَّتَينِ). فقد أجاب عنها العُلماءُ. ورَجَّحَ ابنُ القَيِّمِ وابنُ حَجَرْ وغيرُهما أنَّه وقع مَرَّةً واحدةً."}]
